window.__BANKDATA__["bank-202610-salvage"] = {"bankId": "bank-202610-salvage", "type": "bank", "owner": "david", "bankName": "2026 October salvage", "bankVersion": "sha-96425f38f19d", "questions": [{"qid": "q0001", "minted": "2026-10-19", "retired": false, "type": "mcq", "subject": "rw", "skill": "Words in Context", "tags": ["src:202408usv3:rw1-q1"], "passage": "The reception of Many Ly’s book {{i}}Roots and Wings{{/i}} has been very good. Many reviewers, booksellers, and librarians have _____ the book, and it won the Asian/Pacific American Award for Literature.", "questionText": "Which choice completes the text with the most logical and precise word or phrase?", "choices": ["attacked", "recommended", "overlooked", "misunderstood"], "correctAnswer": 1, "difficulty": null}, {"qid": "q0002", "minted": "2026-10-19", "retired": false, "type": "mcq", "subject": "rw", "skill": "Command of Evidence (Quantitative)", "tags": ["src:202408usv3:rw1-q10"], "passage": "Minimum and Maximum Depths of Stony Coral Species in Caribbean and Indo-Pacific Waters{{table}}Species | Location | Minimum depth (meters) | Maximum depth (meters){{row}}{{i}}Agaricia grahamae{{/i}} | Caribbean | 20 | 115{{row}}{{i}}Acropora bushyensis{{/i}} | Indo-Pacific | 0 | 5{{row}}{{i}}Mussa angulosa{{/i}} | Caribbean | 5 | 30{{row}}{{i}}Indophyllia macassarensis{{/i}} | Indo-Pacific | 20 | 25{{/table}}A marine biologist is researching four stony coral species in Caribbean and Indo-Pacific waters, focusing on sightings of these species in the shallow zone (less than 30 meters below the surface) and the mesophotic zone (30 to 150 meters below the surface). Consulting the table, she notes that the smallest maximum depth is located in _____", "questionText": "Which choice most effectively uses data from the table to complete the statement?", "choices": ["Indo-Pacific waters in the shallow zone.", "Caribbean waters in the shallow zone.", "Indo-Pacific waters in the mesophotic zone.", "Caribbean waters in the mesophotic zone."], "correctAnswer": 0, "difficulty": null}, {"qid": "q0003", "minted": "2026-10-19", "retired": false, "type": "mcq", "subject": "rw", "skill": "Command of Evidence (Quantitative)", "tags": ["src:202408usv3:rw1-q11", "fig:recrop"], "passage": "In a college course on urban affairs, a student asserts that increased traffic congestion in the United States in the 1990s was present both in very large cities such as Philadelphia, Pennsylvania, and smaller areas such as Albany-Schenectady-Troy, New York, and Beaumont, Texas: though those smaller areas may have been less affected by traffic congestion than very large cities, this congestion also worsened in them over time.", "questionText": "Which choice best describes data from the graph that support the student’s claim?", "choices": ["Even though the amount of traffic delay per commuter per year was greater in the Albany-Schenectady-Troy, New York, area than in the Philadelphia, Pennsylvania, area throughout the period from 1990 to 2000, the amounts were nearly identical in 1996.", "In 1992, the amount of traffic delay in the Philadelphia, Pennsylvania, area was less than 30 hours per commuter per year.", "In at least one of the three urban areas shown, the amount of traffic delay was less than 20 hours per commuter per year at one point between 1990 and 2000.", "While the annual number of hours of traffic delay per commuter was always lower in the Albany-Schenectady-Troy, New York, area than in the Philadelphia, Pennsylvania, area for each year between 1990 and 2000, the amount of traffic delay rose in both areas during this period."], "correctAnswer": 3, "difficulty": null, "figure": "data:image/png;base64,"}, {"qid": "q0004", "minted": "2026-10-19", "retired": false, "type": "mcq", "subject": "rw", "skill": "Command of Evidence (Textual)", "tags": ["src:202408usv3:rw1-q12"], "passage": "Past research suggests that pollination by honeybees is responsible for up to 10 percent of total Chinese cabbage crop production. Now researchers are trying to determine how dependent cucumber crop production is on honeybees. The first phase of their study involved shielding some cucumber plants to prevent insects from pollinating them, resulting in those plants having 40 to 90 percent lower crop production than plants that were pollinated normally. However, the researchers claim that the first-phase experiment alone didn’t tell them how much of that difference in crop production is due specifically to excluding honeybees.", "questionText": "Which finding, if true, would most directly support the researchers’ claim?", "choices": ["The shielding used in the first phase of the study did not affect the amount of sunlight the cucumber plants received.", "Other insects like solitary bees also pollinate Chinese cabbage plants, and some studies have allowed them to pollinate normally while excluding honeybees.", "Other insects like squash bees also pollinate cucumber plants, and the shielding in the first phase of the study blocked them as well.", "Honeybees are more commonly used to pollinate cucumber plants than Chinese cabbage plants."], "correctAnswer": 2, "difficulty": null}, {"qid": "q0005", "minted": "2026-10-19", "retired": false, "type": "mcq", "subject": "rw", "skill": "Form, Structure, and Sense", "tags": ["src:202408usv3:rw1-q16"], "passage": "Often anthologized alongside the _____ associated with the Black Arts movement—such as Henry Dumas and Ntozake Shange—Haki Madhubuti’s poem “Quality: Gwendolyn Brooks at 73” stands out for its memorable first lines: “breath, / life after seven decades plus three years / is a lot of breathing.”", "questionText": "Which choice completes the text so that it conforms to the conventions of Standard English?", "choices": ["works of other writer’s", "work’s of other writer’s", "works of other writers", "work’s of other writers"], "correctAnswer": 2, "difficulty": null}, {"qid": "q0006", "minted": "2026-10-19", "retired": false, "type": "mcq", "subject": "rw", "skill": "Boundaries", "tags": ["src:202408usv3:rw1-q17"], "passage": "The part of a compound that determines the compound’s color is _____ the chromophore. One example of a chromophore is hemoglobin, which gives human blood its red color.", "questionText": "Which choice completes the text so that it conforms to the conventions of Standard English?", "choices": ["called—", "called;", "called,", "called"], "correctAnswer": 3, "difficulty": null}, {"qid": "q0007", "minted": "2026-10-19", "retired": false, "type": "mcq", "subject": "rw", "skill": "Boundaries", "tags": ["src:202408usv3:rw1-q18"], "passage": "Released in 1993, the Intel Pentium microchip contained a single CPU, or core, to execute commands. Since then, the average processing power of microchips has increased so drastically—cores now number in the dozens, hundreds, or even _____ the once-revolutionary dual-core technology that replaced the single core chip can be found in everyday items like toasters and toothbrushes.", "questionText": "Which choice completes the text so that it conforms to the conventions of Standard English?", "choices": ["thousands—that", "thousands that—", "thousands. That", "thousands, that"], "correctAnswer": 0, "difficulty": null}, {"qid": "q0008", "minted": "2026-10-19", "retired": false, "type": "mcq", "subject": "rw", "skill": "Boundaries", "tags": ["src:202408usv3:rw1-q19"], "passage": "After finding information about Ronald V. Dellums, who represented California in the United States House of Representatives, the student discovered biographical sketches of two other Black Americans who served in _____ Ralph Harold Metcalfe of Illinois and George Henry White of North Carolina.", "questionText": "Which choice completes the text so that it conforms to the conventions of Standard English?", "choices": ["Congress,", "Congress:", "Congress;", "Congress"], "correctAnswer": 1, "difficulty": null}, {"qid": "q0009", "minted": "2026-10-19", "retired": false, "type": "mcq", "subject": "rw", "skill": "Form, Structure, and Sense", "tags": ["src:202408usv3:rw1-q20"], "passage": "When a given industry—water and electricity are two well-known examples—carries high infrastructural start-up costs and other barriers that discourage competition, _____ of just one or two suppliers per municipality. Such industries are known as natural monopolies.", "questionText": "Which choice completes the text so that it conforms to the conventions of Standard English?", "choices": ["they often consist", "this often consists", "these often consist", "it often consists"], "correctAnswer": 3, "difficulty": null}, {"qid": "q0010", "minted": "2026-10-19", "retired": false, "type": "mcq", "subject": "rw", "skill": "Transitions", "tags": ["src:202408usv3:rw1-q22"], "passage": "There are three basic steps you should follow when planning a scientific inquiry. First, thoroughly research the question you wish to answer. _____ come up with a prediction (also called a hypothesis) about the answer to your question. Third, develop an experiment that can test the accuracy of your hypothesis.", "questionText": "Which choice completes the text with the most logical transition?", "choices": ["For example,", "Second,", "Therefore,", "Instead,"], "correctAnswer": 1, "difficulty": null}, {"qid": "q0011", "minted": "2026-10-19", "retired": false, "type": "mcq", "subject": "rw", "skill": "Transitions", "tags": ["src:202408usv3:rw1-q23"], "passage": "Upon first approaching artist Kurt Wenner’s {{i}}Dies Irae{{/i}}, a colorful scene painted on the surface of a cobblestone street in Mantua, Italy, one might assume a deep hole filled with life-sized, classically styled sculptures had opened up in the street. _____ by expertly applying the principles of perspective, Wenner created merely the illusion of depth.", "questionText": "Which choice completes the text with the most logical transition?", "choices": ["Additionally,", "Next,", "As a result,", "On the contrary,"], "correctAnswer": 3, "difficulty": null}, {"qid": "q0012", "minted": "2026-10-19", "retired": false, "type": "mcq", "subject": "rw", "skill": "Rhetorical Synthesis", "tags": ["src:202408usv3:rw1-q24"], "passage": "While researching a topic, a student has taken the following notes:{{bullets}}Atitalaquia is a municipality in the state of Hidalgo, Mexico.{{item}}Municipalities are governmental regions responsible for providing many public services to their residents.{{item}}One service they provide is street lighting.{{item}}Atitalaquia covers an area of roughly 63 km².{{item}}Hidalgo is divided into 84 municipalities.{{/bullets}}", "questionText": "The student wants to emphasize the size of Atitalaquia. Which choice most effectively uses relevant information from the notes to accomplish this goal?", "choices": ["Providing street lighting is just one example of the public services that municipalities provide.", "Atitalaquia is one of 84 governmental regions, known as municipalities, across Hidalgo.", "Atitalaquia—a governmental region in the state of Hidalgo, Mexico—provides many public services to its residents.", "The municipality of Atitalaquia in Hidalgo, Mexico, covers an area of roughly 63 km²."], "correctAnswer": 3, "difficulty": null}, {"qid": "q0013", "minted": "2026-10-19", "retired": false, "type": "mcq", "subject": "rw", "skill": "Rhetorical Synthesis", "tags": ["src:202408usv3:rw1-q26"], "passage": "{{bullets}}Jean-Michel Basquiat was an American artist who produced more than two thousand drawings and paintings.{{item}}His work {{i}}Untitled (Two Heads on Gold){{/i}} was completed in 1982 and sold at auction in 2003.{{item}}{{i}}Untitled (Two Heads on Gold){{/i}} is composed of acrylic and oil stick on canvas and measures 10,000 square inches in area.{{item}}His work {{i}}Jazz{{/i}} was completed in 1986 and sold at auction in 2020.{{item}}{{i}}Jazz{{/i}} is composed of acrylic, oil, graphite, crayon, and paper collage on wood and measures 1,807 square inches in area.{{/bullets}}", "questionText": "Which choice most effectively uses information from the given sentences to emphasize how the two works are similar?", "choices": ["Artist Jean-Michel Basquiat completed {{i}}Untitled (Two Heads on Gold){{/i}} in 1982, and {{i}}Jazz{{/i}} followed in 1986.", "Between artist Jean-Michel Basquiat’s works {{i}}Untitled (Two Heads on Gold){{/i}} and {{i}}Jazz{{/i}}, the former is the larger of the two.", "Composed by artist Jean-Michel Basquiat in 1982 and 1986, respectively, both {{i}}Untitled (Two Heads on Gold){{/i}} and {{i}}Jazz{{/i}} use acrylic paint as a medium.", "Artist Jean-Michel Basquiat’s work {{i}}Untitled (Two Heads on Gold){{/i}} is composed of acrylic and oil stick, while {{i}}Jazz{{/i}} is composed of acrylic, oil, graphite, crayon, and paper collage."], "correctAnswer": 2, "difficulty": null}, {"qid": "q0014", "minted": "2026-10-19", "retired": false, "type": "mcq", "subject": "rw", "skill": "Rhetorical Synthesis", "tags": ["src:202408usv3:rw1-q27"], "passage": "While researching a topic, a student has taken the following notes:{{bullets}}Onomatopoeias are words that imitate the sounds they represent.{{item}}Words that represent the same sound are often written and pronounced very differently from language to language.{{item}}This variation is due in part to differences in how the languages are structured.{{item}}“Korrrr” is a Batak onomatopoeia that represents the sound of snoring.{{item}}“Hu lu” is a Mandarin Chinese onomatopoeia that represents the sound of snoring.{{/bullets}}", "questionText": "The student wants to contrast two words that represent the same sound. Which choice most effectively uses relevant information from the notes to accomplish this goal?", "choices": ["Though they both represent the sound of snoring, the onomatopoeias “korrrr” (Batak) and “hu lu” (Mandarin Chinese) are written and pronounced very differently.", "Onomatopoeias, words that imitate the sounds they represent, are often written and pronounced very differently from language to language.", "The Batak word “korrrr” and the Mandarin Chinese word “hu lu” are onomatopoeias that represent the sound of snoring.", "The Batak word “korrrr,” which represents the sound of snoring, is an onomatopoeia."], "correctAnswer": 0, "difficulty": null}, {"qid": "q0015", "minted": "2026-10-19", "retired": false, "type": "mcq", "subject": "rw", "skill": "Words in Context", "tags": ["src:202408usv3:rw1-q3"], "passage": "Kelp forests grow underwater along the eastern Pacific Coast. These underwater forests are important to fish and other marine animals. Ocean currents can be powerful and rough, making it difficult for animals to find safe places to hide from predators. The underwater forests slow down the currents. This creates a more _____ environment with calmer waters where animals can take shelter.", "questionText": "Which choice completes the text with the most logical and precise word or phrase?", "choices": ["surprising", "dangerous", "tranquil", "imaginative"], "correctAnswer": 2, "difficulty": null}, {"qid": "q0016", "minted": "2026-10-19", "retired": false, "type": "mcq", "subject": "rw", "skill": "Words in Context", "tags": ["src:202408usv3:rw1-q4"], "passage": "The recently observed gamma ray burst GRB 230307A lasted for 200 seconds, _____ for a burst generated by the merger of neutron stars. Bursts caused by neutron mergers typically last fewer than 2 seconds.", "questionText": "Which choice completes the text with the most logical and precise word or phrase?", "choices": ["an oddity", "a coincidence", "a reprieve", "an incident"], "correctAnswer": 0, "difficulty": null}, {"qid": "q0017", "minted": "2026-10-19", "retired": false, "type": "mcq", "subject": "rw", "skill": "Text Structure and Purpose", "tags": ["src:202408usv3:rw1-q5"], "passage": "Pteropods are small swimming snails with thin, delicate calcium carbonate shells. These animals are thought to be especially vulnerable to ocean acidification due to calcium carbonate’s susceptibility to dissolution at lower pH values. Victoria L. Peck and colleagues recently found that the periostracum (a protective coating on pteropods’ outer shells) prevents this dissolution when intact. Moreover, the team was surprised to discover that even when the periostracum is breached, pteropods can still mitigate damage by rebuilding the inner shell wall.", "questionText": "Which choice best describes the main purpose of the text?", "choices": ["To call for additional research on biological mechanisms that improve pteropod survival rates", "To present findings that suggest that a concern about the effects of ocean acidification on pteropod shells may be unwarranted", "To address some of the ways ocean acidification has altered pteropod behavior over time", "To discuss a conclusion drawn in a study of calcium carbonate’s role in protecting the periostracum of pteropods"], "correctAnswer": 1, "difficulty": null}, {"qid": "q0018", "minted": "2026-10-19", "retired": false, "type": "mcq", "subject": "rw", "skill": "Central Ideas and Details", "tags": ["src:202408usv3:rw1-q7"], "passage": "Guojun He and colleagues studied a food-delivery phone app that is popular in China. The researchers found that having “no cutlery” automatically selected influences whether customers request disposable plastic utensils with their food orders. Based on their results, the researchers concluded that this and other small changes to the app could reduce plastic waste in China by as much as 3.26 million metric tons per year.", "questionText": "According to the text, which choice best describes a conclusion He and colleagues drew from their study?", "choices": ["Production of plastic waste in China is likely to increase in the near future.", "Food-delivery apps that prevent customers from requesting cutlery are becoming more popular.", "Customers who understand how food-delivery apps work make more environmentally friendly choices.", "Small changes to how a food-delivery app works can greatly lower plastic waste."], "correctAnswer": 3, "difficulty": null}, {"qid": "q0019", "minted": "2026-10-19", "retired": false, "type": "mcq", "subject": "rw", "skill": "Central Ideas and Details", "tags": ["src:202408usv3:rw1-q8"], "passage": "The following text is from William Shakespeare’s play {{i}}The Tempest{{/i}}, first performed in 1611. Miranda has lived on an island with her father, Prospero, since she was three years old. Prospero has stated that Miranda likely does not remember anything other than her life on the island.{{br}}{{br}}{{quote}}MIRANDA: ’Tis far off,{{br}}And rather like a dream than an assurance{{br}}That my remembrance warrants. Had I not{{br}}Four or five women once that tended me?{{br}}{{br}}PROSPERO: Thou hadst, and more, Miranda. But how is it{{br}}That this lives in thy mind? What seest thou else{{br}}In the dark backward and abysm of time?{{br}}If thou remember’st ought ere thou camest here,{{br}}How thou camest here thou mayst.{{/quote}}", "questionText": "In the text, which point does Prospero most directly make about Miranda and her memories?", "choices": ["Miranda’s impression of a scene is vague because she is remembering a scenario she had daydreamed about as a child rather than a scenario that had occurred in reality.", "Miranda’s reminiscences about her early childhood have a melancholy quality that betrays her discontented view of her current circumstances.", "Miranda’s ability to summon details of an experience she had before arriving on the island suggests that she may also be able to summon details of her arrival on the island.", "Miranda’s doubts about the accuracy of one recollection of a place other than the island are clouding her judgment and seem to be making her reluctant to explore her recollection of traveling to the island."], "correctAnswer": 2, "difficulty": null}, {"qid": "q0020", "minted": "2026-10-19", "retired": false, "type": "mcq", "subject": "rw", "skill": "Command of Evidence (Quantitative)", "tags": ["src:202408usv3:rw1-q9"], "passage": "Impact of Four Key Industries on Oklahoma Economy in 2017{{table}}Industry | Approximate total contribution by industry | Number of people employed by industry | Average contribution per employee by industry{{row}}Tribal economic activity | $7,312,400,000 | 51,674 | $141,510{{row}}Finance/insurance | $7,281,900,000 | 56,163 | $129,657{{row}}Wholesale trade | $10,723,400,000 | 58,346 | $183,790{{row}}Administration/waste | $5,830,600,000 | 96,964 | $60,132{{/table}}The Chickasaw Nation and the nearly forty other tribes in Oklahoma operate numerous businesses and collectively generate billions of dollars in revenue. Mining, including oil and natural gas production, is a key industry in the state as well. While researching other key industries in Oklahoma for an economics class, a student finds that the average amount contributed to the state’s economy in 2017 by each individual employed in wholesale trade was _____", "questionText": "Which choice most effectively uses data from the table to complete the statement?", "choices": ["$141,510.", "$56,163.", "$183,790.", "$96,964."], "correctAnswer": 2, "difficulty": null}, {"qid": "q0021", "minted": "2026-10-19", "retired": false, "type": "mcq", "subject": "rw", "skill": "Central Ideas and Details", "tags": ["src:202408usv3:rw2-q10"], "passage": "At over a thousand pages across two volumes, {{i}}The Fifty-Year Mission{{/i}}, compiled by Edward Gross and Mark A. Altman, is presented as the “complete, uncensored, unauthorized oral history” as told by the people behind the media franchise Star Trek. The work aspires to be comprehensive by, for example, including accounts from cast and crew members of every Star Trek television series and film to date. But while {{i}}The Fifty-Year Mission{{/i}} is clearly a unique and valuable resource, it has a shortcoming common among oral histories: it lacks a clear authorial point of view that could otherwise unite the various accounts into a cohesive whole.", "questionText": "Which choice best states the main idea of the text?", "choices": ["{{i}}The Fifty-Year Mission{{/i}} includes more accounts from people involved with Star Trek television shows than it does from people involved with Star Trek films.", "The compilers of {{i}}The Fifty-Year Mission{{/i}} had lofty goals for their oral history of the Star Trek franchise, but the published work lacks information about many key events in the franchise’s history.", "The large amount of material compiled into {{i}}The Fifty-Year Mission{{/i}} is surprising given that many of the people involved in the Star Trek franchise did not participate in the oral history project.", "{{i}}The Fifty-Year Mission{{/i}} represents a worthwhile attempt to thoroughly recount the history of the Star Trek franchise, but its approach has an important limitation."], "correctAnswer": 3, "difficulty": null}, {"qid": "q0022", "minted": "2026-10-19", "retired": false, "type": "mcq", "subject": "rw", "skill": "Boundaries", "tags": ["src:202408usv3:rw2-q17"], "passage": "As cheesemaking practices spread throughout Europe and Asia during and after the Neolithic, divergent strategies for preserving milk _____ whereas rennet-coagulated cheesemaking became key to milk preservation in Europe and Southwest Asia, acid-heat coagulation methods became common among nomadic herding populations of the northeastern Eurasian steppe.", "questionText": "Which choice completes the text so that it conforms to the conventions of Standard English?", "choices": ["emerged and", "emerged", "emerged,", "emerged:"], "correctAnswer": 3, "difficulty": null}, {"qid": "q0023", "minted": "2026-10-19", "retired": false, "type": "mcq", "subject": "rw", "skill": "Boundaries", "tags": ["src:202408usv3:rw2-q18"], "passage": "The editors of {{i}}Home Ground: A Guide to the American Landscape{{/i}} turned to the _____ to craft the entry about “hueco,” a term referring to a water-retaining depression in a rock face.", "questionText": "Which choice completes the text so that it conforms to the conventions of Standard English?", "choices": ["novelist Stephen Graham Jones,", "novelist Stephen Graham Jones", "novelist, Stephen Graham Jones,", "novelist, Stephen Graham Jones"], "correctAnswer": 1, "difficulty": null}, {"qid": "q0024", "minted": "2026-10-19", "retired": false, "type": "mcq", "subject": "rw", "skill": "Form, Structure, and Sense", "tags": ["src:202408usv3:rw2-q19"], "passage": "Increased gender diversity is revitalizing the field of economics, according to Harvard’s Claudia Goldin. The trailblazing accomplishments of Goldin, winner of the 2023 Nobel Prize in Economics for her work on women in the labor force, _____ to the value of scholars of diverse backgrounds in spurring research into previously unexplored, but vitally important, topics.", "questionText": "Which choice completes the text so that it conforms to the conventions of Standard English?", "choices": ["attests", "attest", "has attested", "is attesting"], "correctAnswer": 1, "difficulty": null}, {"qid": "q0025", "minted": "2026-10-19", "retired": false, "type": "mcq", "subject": "rw", "skill": "Words in Context", "tags": ["src:202408usv3:rw2-q2"], "passage": "The decline of the giant ground sloth, a species found throughout South America before it became extinct around 8500 BCE, surely had a number of _____ the larger ecosystem in which it existed. The giant ground sloth was part of a complex food web with other organisms, and its disappearance likely affected several other species.", "questionText": "Which choice completes the text with the most logical and precise word or phrase?", "choices": ["sources in", "consequences for", "similarities to", "precedents in"], "correctAnswer": 1, "difficulty": null}, {"qid": "q0026", "minted": "2026-10-19", "retired": false, "type": "mcq", "subject": "rw", "skill": "Form, Structure, and Sense", "tags": ["src:202408usv3:rw2-q20"], "passage": "In the late nineteenth and early twentieth centuries, automobiles were commonly referred to as horseless carriages after the older technology they still resembled. Known as the Brass Era, this period in automotive design is remembered for its grandeur and artistry, its vehicles _____ by collectors for their ornate detailing and gleaming brass fittings.", "questionText": "Which choice completes the text so that it conforms to the conventions of Standard English?", "choices": ["highly prized", "had been highly prized", "are highly prized", "were highly prized"], "correctAnswer": 0, "difficulty": null}, {"qid": "q0027", "minted": "2026-10-19", "retired": false, "type": "mcq", "subject": "rw", "skill": "Boundaries", "tags": ["src:202408usv3:rw2-q22"], "passage": "English poet and Shakespeare contemporary John Donne’s _____ much admired during his lifetime (1572-1631) and in the decades that followed, had, at the time of their enthusiastic rediscovery by the early twentieth-century modernists, been essentially gathering dust for the intervening 250 years.", "questionText": "Which choice completes the text so that it conforms to the conventions of Standard English?", "choices": ["works,", "works, were", "works were", "works had been"], "correctAnswer": 0, "difficulty": null}, {"qid": "q0028", "minted": "2026-10-19", "retired": false, "type": "mcq", "subject": "rw", "skill": "Transitions", "tags": ["src:202408usv3:rw2-q23"], "passage": "Following the American Revolutionary War, North American foodways underwent a radical transformation, fueled in large part by spiking consumer demand for certain grains. The cultivation, trade, and transportation of maize and wheat, _____ reconfigured the continent’s existing regional foodways into a globally oriented food system.", "questionText": "Which choice completes the text with the most logical transition?", "choices": ["by comparison,", "second of all,", "alternatively,", "in particular,"], "correctAnswer": 3, "difficulty": null}, {"qid": "q0029", "minted": "2026-10-19", "retired": false, "type": "mcq", "subject": "rw", "skill": "Transitions", "tags": ["src:202408usv3:rw2-q25"], "passage": "Eirene, one of the eighty known moons of Jupiter, is designated as Jupiter LVII (“LVII” means “57”). Roman numerals typically indicate the order in which the moons were named rather than the order of their proximity to Jupiter. It is incorrect to assume, _____ that Eirene is the fifty-seventh moon from Jupiter in terms of proximity.", "questionText": "Which choice completes the text with the most logical transition?", "choices": ["moreover,", "finally,", "however,", "then,"], "correctAnswer": 3, "difficulty": null}, {"qid": "q0030", "minted": "2026-10-19", "retired": false, "type": "mcq", "subject": "rw", "skill": "Rhetorical Synthesis", "tags": ["src:202408usv3:rw2-q26"], "passage": "While researching a topic, a student has taken the following notes:{{bullets}}Ibn Sina was a Persian philosopher and physician.{{item}}His book {{i}}The Canon of Medicine{{/i}} recorded the most advanced medical knowledge of his time.{{item}}It was published in the year 1025 CE.{{item}}It was used as a medical textbook in Middle Eastern and European universities for centuries.{{/bullets}}", "questionText": "The student wants to identify the year that {{i}}The Canon of Medicine{{/i}} was published. Which choice most effectively uses relevant information from the notes to accomplish this goal?", "choices": ["Ibn Sina recorded the most advanced medical knowledge of his time in his book {{i}}The Canon of Medicine{{/i}}.", "A Persian philosopher and physician wrote a medical textbook called {{i}}The Canon of Medicine{{/i}}.", "{{i}}The Canon of Medicine{{/i}} was a medical textbook used by Middle Eastern and European universities for centuries.", "Ibn Sina’s book {{i}}The Canon of Medicine{{/i}} was published in the year 1025 CE."], "correctAnswer": 3, "difficulty": null}, {"qid": "q0031", "minted": "2026-10-19", "retired": false, "type": "mcq", "subject": "rw", "skill": "Rhetorical Synthesis", "tags": ["src:202408usv3:rw2-q27"], "passage": "While researching a topic, a student has taken the following notes:{{bullets}}There are more than 500 National Wildlife Refuges (NWRs) across the United States.{{item}}The Crocodile Lake NWR is a 6,686-acre area in Florida, on the Atlantic coast.{{item}}It was established to protect the endangered American crocodile.{{item}}The Nestucca Bay NWR is a 457-acre area in Oregon, on the Pacific coast.{{item}}It was established to protect the endangered Aleutian Canada goose.{{/bullets}}", "questionText": "The student wants to provide an overview of the NWR program. Which choice most effectively uses relevant information from the notes to accomplish this goal?", "choices": ["The US’s more than 500 NWRs protect endangered species from coast to coast.", "Both the Crocodile Lake NWR and the Nestucca Bay NWR were established to protect endangered species.", "Oregon’s Nestucca Bay NWR was established to protect the endangered Aleutian Canada goose.", "One of more than 500 NWRs in the US, the Crocodile Lake NWR encompasses 6,686 acres in Florida."], "correctAnswer": 0, "difficulty": null}, {"qid": "q0032", "minted": "2026-10-19", "retired": false, "type": "mcq", "subject": "rw", "skill": "Words in Context", "tags": ["src:202408usv3:rw2-q4"], "passage": "Although our knowledge of the Pliocene epoch and the lives of hominids during this time was once _____, recent analyses of fossils like that of the individual known as LH 4, discovered in Tanzania in 1974, have sharpened our picture of what a day in the life of LH4 may have looked like.", "questionText": "Which choice completes the text with the most logical and precise word or phrase?", "choices": ["unprecedented", "nebulous", "intricate", "concrete"], "correctAnswer": 1, "difficulty": null}, {"qid": "q0033", "minted": "2026-10-19", "retired": false, "type": "mcq", "subject": "rw", "skill": "Text Structure and Purpose", "tags": ["src:202408usv3:rw2-q6"], "passage": "In a study by Mika R. Moran, Daniel A. Rodriguez, and colleagues, residents of Panama City, Panama, and Caracas, Venezuela, were surveyed about parks in their cities. Of the 318 respondents from Panama City, 53.5% indicated that they use the city’s parks, and of the 1,043 respondents from Caracas, 44.7% indicated using city parks. Given that the percentage of Panama City respondents who reported having access to desired nonpark amenities near parks was much lower than that reported by Caracas respondents, the difference in park use can’t be explained by Panama City residents having more access to desired nonpark amenities near parks.", "questionText": "Which choice best describes the overall structure of the text?", "choices": ["An unexpected finding is described, and then that finding is attributed to the method used to collect survey data in Panama City and Caracas.", "An unresolved question about park planning is described, and then examples from a study of Panama City and Caracas are used to answer that question.", "A study involving surveys in Panama City and Caracas is introduced, and then a possible explanation for some of the results is considered and rejected.", "A study of park use in Panama City is described, and then a similar study of park use in Caracas is analyzed to corroborate the findings of the Panama City study."], "correctAnswer": 2, "difficulty": null}, {"qid": "q0034", "minted": "2026-10-19", "retired": true, "retiredDate": "2026-10-19", "supersededBy": "q0111", "retireReason": "the same question as q0111: the same passage, stem and correct answer; only the wrong choices differ", "type": "mcq", "subject": "rw", "skill": "Central Ideas and Details", "tags": ["src:202408usv3:rw2-q9"], "passage": "The following text is from Ralph Waldo Emerson’s 1841 essay “The Method of Nature.”{{br}}{{br}}{{quote}}The scholars are the priests of that thought which establishes the foundations of the earth. No matter what is their special work or profession, they stand for the spiritual interest of the world, and it is a common calamity if they neglect their post in a country where the material interest is so predominant as it is in America.{{/quote}}", "questionText": "Which choice best states the main idea of the text?", "choices": ["Military experience encourages Americans to contemplate aspects of human life that they would not choose to otherwise.", "It is unfortunate that so many intellectuals are concerned with material things rather than ideas.", "Many descriptions of the role of scholars in society unfairly diminish their importance.", "In a country whose citizens are largely preoccupied with tangible gains, it is crucial that some people work to foster and preserve ideas."], "correctAnswer": 3, "difficulty": null}, {"qid": "q0035", "minted": "2026-10-19", "retired": false, "type": "mcq", "subject": "rw", "skill": "Central Ideas and Details", "tags": ["src:202506asiav1:rw1-q10"], "passage": "Spanning the 1920s to the 1980s, Mexican architect Luis Barragán’s prolific career evolved through distinct phases. After traveling to the United States and Europe in the early 1930s and immersing himself in an international architectural discourse, Barragán began incorporating principles derived from functionalism and modernism in his work, as seen in the Chávez Peón de Ochoa House, whose unadorned geometric forms contrast with the historically inspired architecture found in the Aguilar House, one of Barragán’s early projects in Guadalajara.", "questionText": "Which choice best states the main idea of the text?", "choices": ["Barragán’s designs of the Chávez Peón de Ochoa House and the Aguilar House are considered paragons of a functionalist and modernist aesthetic.", "A notable shift in Barragán’s design aesthetic reflects the influence of his time abroad", "Barragán’s early work shows an initial dedication to a modernist aesthetic that he later abandoned", "Barragán’s design of the Aguilar House is considered more experimental than his design for the Chávez Peón de Ochoa House."], "correctAnswer": 1, "difficulty": null}, {"qid": "q0036", "minted": "2026-10-19", "retired": false, "type": "mcq", "subject": "rw", "skill": "Command of Evidence (Quantitative)", "tags": ["src:202506asiav1:rw1-q11"], "passage": "{{table}}Plant | State | Mode | Generators in plant | Average power generation (MWh/yr) | Water source{{row}}J. Woodruff | Florida | peaking | 3 | 193,864 | Lake Seminole Reservoir{{row}}Superior Falls | Michigan | run-of-river | 2 | 10,693 | Montreal River{{row}}Norway | Indiana | run-of-river | 4 | 19,751 | Tippecanoe River{{row}}White River | Wisconsin | run-of-river | 2 | 3,999 | White River{{/table}}In 2021, Rocio Uria-Martínez, Megan M. Johnson, and Rul Shan published a report on hydroelectric power plants operating in the US as recently as 2019, and data from their report are shown in the table. Of the plants in the table, the plant with the lowest average power generated per year in 2019 was located in the state of _____", "questionText": "Which choice most effectively uses data from the table to complete the assertion?", "choices": ["Wisconsin.", "Michigan.", "Florida.", "Indiana."], "correctAnswer": 0, "difficulty": null}, {"qid": "q0037", "minted": "2026-10-19", "retired": false, "type": "mcq", "subject": "rw", "skill": "Command of Evidence (Textual)", "tags": ["src:202506asiav1:rw1-q12"], "passage": "When a company has a new product, it has to decide when to tell people about it. Companies usually announce a new product before it is released and available for purchase. Those announcements can increase consumer excitement, which can mean that more people will buy the product. But {{u}}the effect fades quickly, so companies need to be careful in timing the announcement and the release of a new product.{{/u}}", "questionText": "Which finding, if true, would most directly support the underlined claim?", "choices": ["Consumers tend to prefer new products over older products.", "Consumers are more likely to buy a new product when they already use products from the company making the new product.", "Consumer surveys show low excitement for new products that were announced a long time before they were released.", "The kind of information a company provides about a new product helps determine how likely consumers are to buy the product."], "correctAnswer": 2, "difficulty": null}, {"qid": "q0038", "minted": "2026-10-19", "retired": false, "type": "mcq", "subject": "rw", "skill": "Command of Evidence (Textual)", "tags": ["src:202506asiav1:rw1-q14"], "passage": "Founded in 1965 and originally established as a cultural extension of the United Farm Workers—a union representing many Mexican American agricultural workers at the time—the theater troupe El Teatro Campesino has achieved recognition as a source of inspiration for subsequent Chicano theater companies and as a contributor to the dramatic arts. In an article about the company, a theater historian posits that a significant stylistic influence on El Teatro’s early performances was the audience-mediated slapstick comedy of carpa theater, vaudeville-style shows popular in Mexico and the US Southwest in the 1920s and ’30s.", "questionText": "Which quotation from the article would best illustrate the theater historian’s claim?", "choices": ["“The members of the company, which in addition to founder Luis Valdez consisted entirely of nonprofessional actors, traveled into farm fields, where they, with minimal props and costumes, performed comedy in the form of brief humorous vignettes.”", "“The company was focused on the reality of the present situation and discovered that humor was often found in that reality; consequently, comedy became a tool to convey social critique while entertaining and inspiring audiences.”", "“The company relied heavily on satire, humor, and references to contemporary popular culture as well as a make-do aesthetic—often referred to as rasquache—that reflected not only the troupe’s limited financial resources but also its sociopolitical message.”", "“The company presented actos, short comedy sketches, that often relied on exaggerated physical humor to groups of agricultural workers, whose reactions—enthusiastic cheers of appreciation and, occasionally, loud boos of disapproval—promoted improvisation.”"], "correctAnswer": 3, "difficulty": null}, {"qid": "q0039", "minted": "2026-10-19", "retired": false, "type": "mcq", "subject": "rw", "skill": "Inferences", "tags": ["src:202506asiav1:rw1-q15"], "passage": "In Switzerland, the white fuzzy mountain flowers known as edelweiss are widely treated as a symbol of strength and courage. Although edelweiss can thrive in extreme conditions, they aren’t notably tougher or harder to reach than other mountain flowers growing in the Swiss Alps. Historian Tobias Scheidegger has shown that the popular view of the flowers originated in the mid-1800s when mountain climbing became popular in Switzerland. Mountain climbers spread the idea that the flowers grew only in steep, icy terrains that were dangerous to climb to. Scheidegger says that these claims were self-interested. He suggests that mountain climbers presented edelweiss in this way in order to _____", "questionText": "Which choice most logically completes the text?", "choices": ["share their observations about the unusual characteristics of edelweiss with scientists.", "encourage more flower enthusiasts to explore the Swiss Alps.", "make themselves appear brave and strong for being able to climb to difficult places where edelweiss supposedly grew.", "prove that edelweiss were more common in the Swiss Alps than in other mountain regions in Europe."], "correctAnswer": 2, "difficulty": null}, {"qid": "q0040", "minted": "2026-10-19", "retired": false, "type": "mcq", "subject": "rw", "skill": "Form, Structure, and Sense", "tags": ["src:202506asiav1:rw1-q16"], "passage": "A number of scientific phenomena have been named after nineteenth-century Czech physiologist Jan Evangelista Purkinje, including the Purkinje effect, which _____ the eye’s tendency to perceive objects as blue tinted in low-light conditions.", "questionText": "Which choice completes the text so that it conforms to the conventions of Standard English?", "choices": ["has been", "will have been", "was", "is"], "correctAnswer": 3, "difficulty": null}, {"qid": "q0041", "minted": "2026-10-19", "retired": false, "type": "mcq", "subject": "rw", "skill": "Form, Structure, and Sense", "tags": ["src:202506asiav1:rw1-q17"], "passage": "The fibularis longus and the _____ move the fibula and humerus, respectively.", "questionText": "Which choice completes the text so that it conforms to the conventions of Standard English?", "choices": ["brachialis are cylindrical in shape, which are skeletal muscles, and help", "brachialis are cylindrical in shape and help, which are skeletal muscles,", "brachialis, which are skeletal muscles, are cylindrical in shape and help", "brachialis are cylindrical, which are skeletal muscles, in shape and help"], "correctAnswer": 2, "difficulty": null}, {"qid": "q0042", "minted": "2026-10-19", "retired": false, "type": "mcq", "subject": "rw", "skill": "Boundaries", "tags": ["src:202506asiav1:rw1-q18"], "passage": "It was April of 1885 when Vincent van Gogh completed _____ of dozens to be featured in the upcoming exhibition, is an important part of Van Gogh’s body of work.", "questionText": "Which choice completes the text so that it conforms to the conventions of Standard English?", "choices": ["{{i}}Study of Two Peasants{{/i}}, the drawing, one", "{{i}}Study of Two Peasants{{/i}}. The drawing, one", "{{i}}Study of Two Peasants{{/i}}, the drawing. One", "{{i}}Study of Two Peasants{{/i}} the drawing. One"], "correctAnswer": 1, "difficulty": null}, {"qid": "q0043", "minted": "2026-10-19", "retired": false, "type": "mcq", "subject": "rw", "skill": "Boundaries", "tags": ["src:202506asiav1:rw1-q19"], "passage": "Fernando Palma Rodríguez creates robotic sculptures that combine mechanical elements with materials like feathers, soil, and seeds. The artist is from a rural farming community outside Mexico City, and he studied engineering in college. The natural and mechanical _____ highlight these two aspects of his background.", "questionText": "Which choice completes the text so that it conforms to the conventions of Standard English?", "choices": ["materials, that Palma Rodríguez uses in his art", "materials that Palma Rodríguez uses in his art", "materials that Palma Rodríguez uses in his art,", "materials, that Palma Rodríguez uses in his art,"], "correctAnswer": 1, "difficulty": null}, {"qid": "q0044", "minted": "2026-10-19", "retired": false, "type": "mcq", "subject": "rw", "skill": "Transitions", "tags": ["src:202506asiav1:rw1-q21"], "passage": "The eruption of Rusty Geyser in Yellowstone National Park is caused by a sequence of events. First, water seeps down through narrow channels in the bedrock. _____ magma heats the water and turns it into steam. Finally, that steam builds up enough pressure in the narrow channels to force the water above it to burst out of the ground.", "questionText": "Which choice completes the text with the most logical transition?", "choices": ["Similarly,", "On the contrary,", "First of all,", "Next,"], "correctAnswer": 3, "difficulty": null}, {"qid": "q0045", "minted": "2026-10-19", "retired": false, "type": "mcq", "subject": "rw", "skill": "Rhetorical Synthesis", "tags": ["src:202506asiav1:rw1-q23"], "passage": "While researching a topic, a student has taken the following notes:{{bullets}}Igneous rock is one of the three main types of rock.{{item}}It is formed when molten rock, known as magma or lava, cools.{{item}}Intrusive igneous rock forms when molten rock cools deep within Earth’s crust.{{item}}Extrusive igneous rock forms when molten rock exits Earth’s crust and cools on the surface.{{item}}Acadia National Park in Maine contains examples of intrusive igneous rock.{{item}}Crater Lake National Park in Oregon contains examples of extrusive igneous rock.{{/bullets}}", "questionText": "The student wants to contrast how the igneous rock at the two national parks formed. Which choice most effectively uses relevant information from the notes to accomplish this goal?", "choices": ["Acadia National Park contains examples of intrusive igneous rock, the other type of igneous rock is called extrusive igneous rock.", "Acadia National Park’s igneous rock formed from molten rock that cooled deep within Earth’s crust, whereas Crater Lake National Park’s igneous rock formed from molten rock that cooled after it exited Earth’s crust.", "Acadia National Park and Crater Lake National Park both contain igneous rock, which is formed when molten rock cools.", "Two types of igneous rock, which is formed when molten rock cools, are intrusive igneous rock and extrusive igneous rock, both of which can be found in national parks."], "correctAnswer": 1, "difficulty": null}, {"qid": "q0046", "minted": "2026-10-19", "retired": false, "type": "mcq", "subject": "rw", "skill": "Rhetorical Synthesis", "tags": ["src:202506asiav1:rw1-q24"], "passage": "While researching a topic, a student has taken the following notes:{{bullets}}{{i}}Morning Haiku{{/i}} (2010) is a book of poetry by African American poet Sonia Sanchez.{{item}}Each poem in the book is a sequence of haiku.{{item}}According to the book’s publisher, Penguin Random House, the book “celebrates the gifts of life and mourns the deaths of revered African American figures.”{{item}}The poem “15 haiku (for Toni Morrison)” is written as a sequence of fifteen haiku.{{item}}The poem “7 haiku (for Ray Brown)” is written as a sequence of seven haiku.{{/bullets}}", "questionText": "The student wants to contrast the number of haiku in each poem. Which choice most effectively uses relevant information from the notes to accomplish this goal?", "choices": ["The poem “15 haiku (for Toni Morrison)” consists of fifteen haiku, whereas the poem “7 haiku (for Ray Brown)” consists of seven.", "Both “15 haiku (for Toni Morrison)” and “7 haiku (for Ray Brown)” can be found in Sanchez’s 2010 collection {{i}}Morning Haiku{{/i}}.", "While “15 haiku (for Toni Morrison)” is about writer Toni Morrison, “7 haiku (for Ray Brown)” is about bassist Ray Brown.", "The poems in {{i}}Morning Haiku{{/i}} celebrate the lives or mourn the deaths of “revered African American figures,” according to the book’s publisher, Penguin Random House."], "correctAnswer": 0, "difficulty": null}, {"qid": "q0047", "minted": "2026-10-19", "retired": false, "type": "mcq", "subject": "rw", "skill": "Rhetorical Synthesis", "tags": ["src:202506asiav1:rw1-q25"], "passage": "While researching a topic, a student has taken the following notes:{{bullets}}The Japanese Ministry of the Environment made a list of 100 soundscapes of Japan.{{item}}Each soundscape on the list was selected for its cultural significance to Japan.{{item}}The sound of crickets on the banks of the Yodo River is on the list.{{item}}The sound of water flowing over Nachi Falls is on the list.{{/bullets}}", "questionText": "The student wants to indicate that both soundscapes are on the list. Which choice most effectively uses relevant information from the notes to accomplish this goal?", "choices": ["Both the sound of crickets on the banks of the Yodo River and the sound of water flowing over Nachi Falls are on the list.", "The sound of water flowing over Nachi Falls is on the list.", "The Japanese Ministry of the Environment made a list of 100 culturally significant soundscapes of Japan.", "Each soundscape on the list, including the sound of crickets on the banks of the Yodo River, was selected for its cultural significance to Japan."], "correctAnswer": 0, "difficulty": null}, {"qid": "q0048", "minted": "2026-10-19", "retired": false, "type": "mcq", "subject": "rw", "skill": "Rhetorical Synthesis", "tags": ["src:202506asiav1:rw1-q27"], "passage": "While researching a topic, a student has taken the following notes:{{bullets}}Australian ecologist Alison Lullfitz studied the distribution of {{i}}Platysace deflexa{{/i}} (youlk), a small shrub with edible tubers.{{item}}Lullfitz found that youlk plants gathered at sites across southwest Australia had very similar DNA despite differences in soil conditions.{{item}}Lullfitz hypothesized that humans had transported the plant throughout the region.{{item}}Lullfitz consulted Shandel Cummings and Lynette Knapp, members of the area’s Noongar Aboriginal group.{{item}}Cummings and Knapp confirmed that their ancestors carried youlk when traveling across the region.{{/bullets}}", "questionText": "The student wants to explain Cummings and Knapp’s contribution to Lullfitz’s study. Which choice most effectively uses relevant information from the notes to accomplish this goal?", "choices": ["Lullfitz found that Cummings and Knapp had information relevant to her study of {{i}}Platysace deflexa{{/i}}’s distribution.", "Cummings and Knapp confirmed that DNA sequences from the {{i}}Platysace deflexa{{/i}} plants Lullfitz had gathered were in fact very similar.", "Lullfitz consulted Cummings and Knapp, members of the Noongar Aboriginal group, who assisted with her study of {{i}}Platysace deflexa{{/i}}, a small shrub with edible tubers.", "By indicating that their ancestors transported {{i}}Platysace deflexa{{/i}}, Cummings and Knapp provided information that supported Lullfitz’s hypothesis."], "correctAnswer": 3, "difficulty": null}, {"qid": "q0049", "minted": "2026-10-19", "retired": false, "type": "mcq", "subject": "rw", "skill": "Words in Context", "tags": ["src:202506asiav1:rw1-q3"], "passage": "The following text is adapted from George Bernard Shaw’s 1905 play {{i}}Major Barbara{{/i}}.{{br}}{{br}}{{quote}}LADY BRITOMART: You must learn to face life seriously, Stephen. I really cannot bear the whole burden of our family affairs any longer. You must advise me: you must {{u}}assume{{/u}} the responsibility.{{br}}{{br}}STEPHEN: I!{{br}}{{br}}LADY BRITOMART: Yes, you, of course. You were 24 last June.{{/quote}}", "questionText": "As used in the text, what does the word “assume” most nearly mean?", "choices": ["Infer", "Mimic", "Undertake", "Presuppose"], "correctAnswer": 2, "difficulty": null}, {"qid": "q0050", "minted": "2026-10-19", "retired": false, "type": "mcq", "subject": "rw", "skill": "Text Structure and Purpose", "tags": ["src:202506asiav1:rw1-q5"], "passage": "Saturn is the first planet in our solar system to be discovered to have more than 100 moons orbiting around it. A team of astronomers using the Canada-France-Hawaii Telescope (CFHT) in Hawaii detected 62 undiscovered moons that were previously too small or too dim to see. Saturn now outranks Jupiter as the planet in our solar system with the most observed moons.", "questionText": "Which choice best states the main purpose of the text?", "choices": ["To note a new finding about the number of Saturn’s moons", "To explain how the CFHT works", "To describe the atmospheric conditions of Jupiter", "To discuss the history of Hawaii"], "correctAnswer": 0, "difficulty": null}, {"qid": "q0051", "minted": "2026-10-19", "retired": false, "type": "mcq", "subject": "rw", "skill": "Text Structure and Purpose", "tags": ["src:202506asiav1:rw1-q6"], "passage": "The following text is from George Eliot’s 1857 short story “The Sad Fortunes of the Rev. Amos Barton.” In the text, the narrator addresses the reader directly and alludes to a discussion among Rev. Amos Barton’s neighbors.{{br}}{{br}}{{quote}}It was happy for the Rev. Amos Barton that he did not, like us, overhear the conversation recorded in the last chapter. Indeed, what mortal is there of us, who would find his satisfaction enhanced by an opportunity of comparing the picture he presents to himself of his own doings, with the picture they make on the mental retina of his neighbours? We are poor plants buoyed up by the air-vessels of our own conceit: alas for us, if we get a few pinches that empty us of that windy self-subsistence! The very capacity for good would go out of us.{{/quote}}", "questionText": "Which choice best states the overall structure of the text?", "choices": ["The narrator expresses relief that a disagreement was resolved more expediently than expected and then indicates how the situation might have gone differently", "The narrator comments on the fact that a character remains unaware of how he is viewed by others and then generalizes about the problem of learning others’ opinions of one’s own actions.", "The narrator summarizes an earlier event involving a specific character and then anticipates the later significance it will have for that character", "The narrator implies that a character is not well liked by his neighbors and then uses an extended comparison to demonstrate why their negative opinion of him is largely justified."], "correctAnswer": 1, "difficulty": null}, {"qid": "q0052", "minted": "2026-10-19", "retired": false, "type": "mcq", "subject": "rw", "skill": "Cross-Text Connections", "tags": ["src:202506asiav1:rw1-q8"], "passage": "Text 1{{br}}{{br}}Yale University and the investment bank JPMorgan Chase are two of the many institutions offering training programs in entrepreneurship. {{u}}But what results do such programs produce?{{/u}} In a study of college students in Sweden, researcher Ove Hansemark addressed this question and found that participants showed strong belief in their entrepreneurial capabilities after receiving entrepreneurial training.{{br}}{{br}}Text 2{{br}}{{br}}While studies of entrepreneurial training typically report positive results, a close look at these studies reveals widespread methodological shortcomings. For instance, a 1998 study by Ove Hansemark found benefits of entrepreneurial education for Swedish college students, but the study used a very small sample of only 19 students, making it difficult to say whether the training actually had an effect.", "questionText": "Based on the texts, how would the author of Text 2 most likely answer the underlined question in Text 1?", "choices": ["Although the programs may seem to produce positive results, close analysis of studies of the programs shows that they produce negative results just as frequently.", "It is unknown what results the programs produce because studies of them are often designed in ways that do not allow for definitive conclusions.", "Most of the programs do not actually produce positive results even though program participants tend to regard them as beneficial.", "The programs tend to produce inconsistent results because they vary substantially in their methods and aims."], "correctAnswer": 1, "difficulty": null}, {"qid": "q0053", "minted": "2026-10-19", "retired": false, "type": "mcq", "subject": "rw", "skill": "Central Ideas and Details", "tags": ["src:202506asiav1:rw1-q9"], "passage": "The 2020 novel {{i}}The Only Good Indians{{/i}} confirmed that Stephen Graham Jones is one of the most talented writers of horror fiction today. By featuring main characters who are Blackfeet, like Jones himself, the novel also helped to ensure that Indigenous people have a place within the horror genre. But Jones is hardly the only Indigenous voice in horror. Métis author Cherie Dimaline has also written in the genre. Her acclaimed 2019 novel {{i}}Empire of Wild{{/i}} is set in a Métis community in southern Canada.", "questionText": "According to the text, Stephen Graham Jones and Cherie Dimaline are similar in what way?", "choices": ["Both have published fictional works featuring main characters who are Blackfeet.", "Both are citizens of the Blackfeet Nation.", "Both are Indigenous authors who have written horror fiction.", "Both have said that they don’t like reading horror fiction even though they write it."], "correctAnswer": 2, "difficulty": null}, {"qid": "q0054", "minted": "2026-10-19", "retired": false, "type": "mcq", "subject": "rw", "skill": "Command of Evidence (Textual)", "tags": ["src:202506asiav1:rw2-q10"], "passage": "To detect information about water flow, fish have sensors running from the snout tip down the sides of the head. Yuzo R. Yanagisuru, Otar Akanyeti, and James C. Liao conducted tests to find where the difference in pressure is greatest between two adjacent sensors because, according to the researchers, as these pressure differences increase, so does the amount of information available to the fish. Using the ratio of head width to length, they found that the greatest pressure difference is closer to the snout for narrower heads (lower ratio of width to length) and farther from the snout for wider heads (higher ratio of width to length). Based on this finding, a second team of researchers has hypothesized that the sensors where information is greatest are likely more sensitive than the rest.", "questionText": "Which finding, if true, would most directly support the second research team’s hypothesis?", "choices": ["The longnose gar ({{i}}Lepisosteus osseus{{/i}}) has a much narrower head than the devil catfish ({{i}}Bagarius bagarius{{/i}}), and the most sensitive sensors of the longnose gar are closer to the snout than are those of the devil catfish.", "The longnose gar ({{i}}Lepisosteus osseus{{/i}}) has a much narrower head than the devil catfish ({{i}}Bagarius bagarius{{/i}}), and the most sensitive sensors for both are very close to their snouts.", "The longnose gar ({{i}}Lepisosteus osseus{{/i}}) has a much narrower head than the devil catfish ({{i}}Bagarius bagarius{{/i}}), and while the sensors nearest the snout for the longnose gar are more sensitive than the others, for the devil catfish all sensors are equally sensitive.", "The longnose gar ({{i}}Lepisosteus osseus{{/i}}) has a much narrower head than the devil catfish ({{i}}Bagarius bagarius{{/i}}), and the most sensitive sensors for the devil catfish are closer to the snout than are those for the longnose gar."], "correctAnswer": 0, "difficulty": null}, {"qid": "q0055", "minted": "2026-10-19", "retired": false, "type": "mcq", "subject": "rw", "skill": "Command of Evidence (Textual)", "tags": ["src:202506asiav1:rw2-q12"], "passage": "In a series of experiments, Julio Sevilla and Claudia Townsend showed that manipulating the space between products in store displays can influence consumers’ views of those products. Participants in several of the experiments regarded the same products in the same (generic) retail settings as significantly more valuable when the product-to-space ratio was low than when it was high. But in one of the experiments, Sevilla and Townsend arranged the same jewelry with different levels of intervening space at an upscale retailer (Tiffany & Co.) and a relatively inexpensive retailer (Forever 21). The result of this experiment suggests that a store context associated with inexpensive products may moderate the effect Sevilla and Townsend observed in their other experiments.", "questionText": "Which finding, if true, would most directly support the research team’s result?", "choices": ["At both Tiffany & Co. and Forever 21, participants judged jewelry spaced far apart to be less valuable than jewelry spaced close together, but the difference in perceived value was significantly greater at Tiffany & Co. than at Forever 21.", "When jewelry was spaced far apart, participants judged the jewelry at Tiffany & Co. to be more valuable than the jewelry at Forever 21, but when jewelry was spaced close together, participants judged the jewelry at Tiffany & Co. to be less valuable than the jewelry at Forever 21.", "At Tiffany & Co., participants judged jewelry spaced far apart to be substantially more valuable than jewelry spaced close together, but at Forever 21, participants judged jewelry spaced far apart to be only slightly more valuable than jewelry spaced close together.", "Participants judged jewelry spaced far apart at Tiffany & Co. to be similar in value to jewelry spaced far apart at Forever 21, but participants judged jewelry spaced close together at Tiffany & Co. to be more valuable than jewelry spaced close together at Forever 21."], "correctAnswer": 2, "difficulty": null}, {"qid": "q0056", "minted": "2026-10-19", "retired": false, "type": "mcq", "subject": "rw", "skill": "Command of Evidence (Textual)", "tags": ["src:202506asiav1:rw2-q13"], "passage": "{{i}}The Clouds{{/i}} is a 423 BCE play by Aristophanes, originally written in ancient Greek. At the time, professional intellectuals called sophists taught paying customers a variety of subjects and sometimes engaged in what would now be described as research. Aristophanes satirizes sophists’ practices and views as foolish, as seen when the character _____", "questionText": "Which choice most effectively uses a quotation from a translation of {{i}}The Clouds{{/i}} to illustrate the claim?", "choices": ["Strepsiades, after taking lessons from a sophist, says to his son, “Approach, that you may know more, and I will tell you a thing by learning which you will be a man. But see that you do not teach this to any one.”", "Socrates, a sophist, says to a potential customer, “I wish to briefly learn from you if you are possessed of a good memory.”", "Strepsiades encourages his son to learn to be a sophist, saying, “If you have any concern for your father’s patrimony, become one of them.”", "Socrates, a sophist, explains why he studies astronomy while sitting in a basket hanging a few feet off the ground, saying, “I should not have rightly discovered things celestial if I had not suspended the intellect, and mixed the thought in a subtle form with its kindred air.”"], "correctAnswer": 3, "difficulty": null}, {"qid": "q0057", "minted": "2026-10-19", "retired": false, "type": "mcq", "subject": "rw", "skill": "Form, Structure, and Sense", "tags": ["src:202506asiav1:rw2-q16"], "passage": "Established in 1936 by African American novelist Richard Wright, _____ it would become a vital part of the creative movement known as the Chicago Black Renaissance.", "questionText": "Which choice completes the text so that it conforms to the conventions of Standard English?", "choices": ["the South Side Writers Group provided a valuable forum for Chicago writers to share ideas;", "writers shared ideas at a valuable forum known as the South Side Writers Group in Chicago;", "Chicago was where the South Side Writers Group provided a valuable forum for writers to share ideas;", "Chicago writers in the South Side Writers Group had a valuable forum for sharing ideas;"], "correctAnswer": 0, "difficulty": null}, {"qid": "q0058", "minted": "2026-10-19", "retired": false, "type": "mcq", "subject": "rw", "skill": "Boundaries", "tags": ["src:202506asiav1:rw2-q17"], "passage": "The 1948 founding of the American GI Forum and the 1946 Mendez v. Westminster court decision are regarded as important events in US civil rights _____ former establishing a Latino rights advocacy group and the latter legally affirming the rights of Latino students.", "questionText": "Which choice completes the text so that it conforms to the conventions of Standard English?", "choices": ["history the", "history, as the", "history, the", "history. The"], "correctAnswer": 2, "difficulty": null}, {"qid": "q0059", "minted": "2026-10-19", "retired": false, "type": "mcq", "subject": "rw", "skill": "Form, Structure, and Sense", "tags": ["src:202506asiav1:rw2-q18"], "passage": "Trisyllabic words _____ as dactyls in English metrical verse, such as “article” and “sleepier,” consist of one stressed syllable followed by two unstressed syllables.", "questionText": "Which choice completes the text so that it conforms to the conventions of Standard English?", "choices": ["have been classified", "are classified", "can be classified", "classified"], "correctAnswer": 3, "difficulty": null}, {"qid": "q0060", "minted": "2026-10-19", "retired": false, "type": "mcq", "subject": "rw", "skill": "Words in Context", "tags": ["src:202506asiav1:rw2-q2"], "passage": "The following text is adapted from Neera’s 1886 novel {{i}}Teresa{{/i}}, translated by Martha King in 1998.{{br}}{{br}}{{quote}}Beyond the [porch] extended a piece of land, with some exaggeration called a garden. In truth, it had some flower beds that at first sight {{u}}confirmed{{/u}} the illusion, particularly at that time of year; since the pansies were in bloom with their infinite shades, with the intense velvet of their dark leaves and the luminous silk of their pale leaves.{{/quote}}", "questionText": "As used in the text, what does the word “confirmed” most nearly mean?", "choices": ["Necessitated", "Substantiated", "Designated", "Promised"], "correctAnswer": 1, "difficulty": null}, {"qid": "q0061", "minted": "2026-10-19", "retired": false, "type": "mcq", "subject": "rw", "skill": "Form, Structure, and Sense", "tags": ["src:202506asiav1:rw2-q21"], "passage": "The Museum of Modern Art’s vast collection of oil paintings, which includes James Ensor’s {{i}}Tribulations of Saint Anthony{{/i}} and Yasuo Kuniyoshi’s {{i}}Self-Portrait as a Golf Player{{/i}}, _____ among its most captivating offerings.", "questionText": "Which choice completes the text so that it conforms to the conventions of Standard English?", "choices": ["remain", "have remained", "remains", "have been remaining"], "correctAnswer": 2, "difficulty": null}, {"qid": "q0062", "minted": "2026-10-19", "retired": false, "type": "mcq", "subject": "rw", "skill": "Transitions", "tags": ["src:202506asiav1:rw2-q22"], "passage": "The traditional process of Turkish paper marbling (ebru) generally proceeds like this: First, the artisan fills a shallow tray with a water bath solution. Next, the artisan adds inks or paints to the solution, which can then be manipulated into intricate designs. _____ the artisan slips paper in and out of the liquid, transferring the design onto the paper.", "questionText": "Which choice completes the text with the most logical transition?", "choices": ["Nevertheless,", "Therefore,", "Actually,", "Finally,"], "correctAnswer": 3, "difficulty": null}, {"qid": "q0063", "minted": "2026-10-19", "retired": false, "type": "mcq", "subject": "rw", "skill": "Transitions", "tags": ["src:202506asiav1:rw2-q24"], "passage": "The geologic principle of cross-cutting relationships states that an intrusion is younger than the rocks through which it cuts. _____ geophysicists analyzing a given rock formation can ascertain that an igneous intrusion that bisects a layer of 358.9-million-year-old Tournaisian rock but not the 303.7-million-year-old Gzhelian rock above it is younger than the former but older than the latter.", "questionText": "Which choice completes the text with the most logical transition?", "choices": ["Accordingly,", "Moreover,", "To this end,", "That being said,"], "correctAnswer": 0, "difficulty": null}, {"qid": "q0064", "minted": "2026-10-19", "retired": false, "type": "mcq", "subject": "rw", "skill": "Rhetorical Synthesis", "tags": ["src:202506asiav1:rw2-q25"], "passage": "While researching a topic, a student has taken the following notes:{{bullets}}1926: The US Congress gave the US Commerce Department authority to regulate safety standards in the fledgling commercial airline industry.{{item}}1938: Congress transferred this authority to a new independent government agency called the Civil Aeronautics Authority (CAA).{{item}}1958: Congress transferred authority from the CAA to the newly established Federal Aviation Administration (FAA).{{item}}The FAA’s first administrator, Elwood R. Quesada, updated safety standards and technologies for the era of commercial jets.{{item}}The FAA remains the regulatory authority for airline safety.{{/bullets}}", "questionText": "The student wants to specify the order in which different government entities were given the authority to regulate airline safety in the US. Which choice most effectively uses relevant information from the notes to accomplish this goal?", "choices": ["The authority to regulate US airline safety transferred from the US Commerce Department to the CAA in 1938, then from the CAA to the FAA in 1958.", "The CAA had the authority to regulate safety for US airlines from 1938 until 1958, at which point authority was transferred to the US Commerce Department by Elwood R. Quesada.", "The FAA, CAA, and the US Commerce Department all had the authority to regulate US airline safety, but they possessed this authority at different times.", "The FAA has regulated airline safety since it was established by the US Congress in 1958."], "correctAnswer": 0, "difficulty": null}, {"qid": "q0065", "minted": "2026-10-19", "retired": false, "type": "mcq", "subject": "rw", "skill": "Rhetorical Synthesis", "tags": ["src:202506asiav1:rw2-q26"], "passage": "While researching a topic, a student has taken the following notes:{{bullets}}R. Oleksy, L. Giuggioli, and T.J. McKetterick published a study in 2017.{{item}}In it, the researchers found that ingestion by bats had a positive effect on the germination of {{i}}Ficus grevei{{/i}} plant seeds.{{item}}Jorge E. López and C. Vaughan published a study in 2004.{{item}}In it, the researchers found that ingestion by bats had a neutral effect on the germination of {{i}}Senna fruticosa{{/i}} plant seeds.{{item}}J.M. Palmeirim, D.L. Gorchoy, and S. Stoleson published a study in 1989.{{item}}In it, the researchers found that ingestion by bats had a negative effect on the germination of {{i}}Piper friedrichsthalii{{/i}} plant seeds.{{/bullets}}", "questionText": "The student wants to make a generalization about the germination of seeds ingested by bats. Which choice most effectively uses relevant information from the notes to accomplish this goal?", "choices": ["Seed ingestion by bats can have varying effects on seed germination.", "Over the years, researchers have studied the effect that seed germination has had on ingestion by bats.", "As was found in the 2017 study, ingestion by bats has a negative effect on the germination of plant seeds.", "Bat ingestion has consistently been found to have a positive effect on seed germination."], "correctAnswer": 0, "difficulty": null}, {"qid": "q0066", "minted": "2026-10-19", "retired": false, "type": "mcq", "subject": "rw", "skill": "Rhetorical Synthesis", "tags": ["src:202506asiav1:rw2-q27"], "passage": "{{bullets}}Linguists use phonemes to represent the smallest possible units of sound within a word.{{item}}In English, the phoneme /p/ has labial articulation, which means it is produced using one or both lips, such as in the word “pan.”{{item}}The phoneme /z/ has alveolar articulation, which means it is produced by placing the tongue against or near the roof of the mouth, such as in the word “zoo.”{{item}}/p/ is plosive, a term used for sounds in which air flow is at first fully blocked.{{item}}/z/ is fricative, a term used for sounds in which air flow is partially blocked.{{/bullets}}", "questionText": "Which choice most effectively uses information from the given sentences to explain plosive phonemes?", "choices": ["The phoneme /p/, a unit of sound in which air flow is at first fully blocked, has labial articulation.", "The phoneme /p/ in the word “pan” is plosive and is produced using both lips.", "The linguistic term of fricative is used for units of sound in which air flow is partially blocked.", "In linguistics, plosive is a term used for units of sound in which airflow is at first fully blocked."], "correctAnswer": 3, "difficulty": null}, {"qid": "q0067", "minted": "2026-10-19", "retired": false, "type": "mcq", "subject": "rw", "skill": "Words in Context", "tags": ["src:202506asiav1:rw2-q3"], "passage": "If confirmed by other researchers, a newly reported measurement of W boson’s mass could _____ the dominant theory of particle physics, the standard model, as the new measurement differs significantly from the standard model’s prediction of the elementary particle’s mass.", "questionText": "Which choice completes the text with the most logical and precise word or phrase?", "choices": ["satisfy", "simplify", "overtake", "undermine"], "correctAnswer": 3, "difficulty": null}, {"qid": "q0068", "minted": "2026-10-19", "retired": false, "type": "mcq", "subject": "rw", "skill": "Words in Context", "tags": ["src:202506asiav1:rw2-q4"], "passage": "Theater and film scholars often draw parallels between the lives of performers and aspects of roles they’ve played; however, the most insightful of these discussions, such as Linda Costanzo Cahir’s consideration of resemblances between actor Vivien Leigh and the character Blanche DuBois, maintain a rigid distinction between the actor and the character, taking care never to _____ them.", "questionText": "Which choice completes the text with the most logical and precise word or phrase?", "choices": ["conflate", "epitomize", "lambaste", "overshadow"], "correctAnswer": 0, "difficulty": null}, {"qid": "q0069", "minted": "2026-10-19", "retired": false, "type": "mcq", "subject": "rw", "skill": "Text Structure and Purpose", "tags": ["src:202506asiav1:rw2-q6"], "passage": "In Muscogee, an Indigenous language from the southeastern region of what is now the United States, hátki means “white,” whereas háthaki is used to refer to two or more white things. This phenomenon, in which an element of a root word is repeated, sometimes with modification, within another word that is related to the root word, is called reduplication. In this case, the element “há” in hátki gets repeated in háthaki. There are many examples of this type of reduplication in Muscogee.", "questionText": "Which choice best describes the overall structure of the text?", "choices": ["It identifies the most frequently occurring words in Muscogee, explains why it is difficult to translate those words into English, and then provides examples of languages other than English into which those words can be translated.", "It explains the phenomenon of reduplication, discusses why reduplication has been controversial among scholars, and then argues that an analysis of Muscogee could help resolve that controversy.", "It describes the relationship between Muscogee and several other languages, raises a question about the nature of that relationship, and then answers that question.", "It presents some specific words in Muscogee, describes the general linguistic phenomenon exemplified by those words, and then states that this phenomenon occurs frequently in Muscogee."], "correctAnswer": 3, "difficulty": null}, {"qid": "q0070", "minted": "2026-10-19", "retired": false, "type": "mcq", "subject": "rw", "skill": "Central Ideas and Details", "tags": ["src:202506asiav1:rw2-q9"], "passage": "Philosophers note that many people have an intuitive sense that while we ought not to lie, there may be circumstances in which lying is permissible. If this intuition is correct and we lack an inviolable duty to speak truthfully, what grounds opposition to lying in the first place? Japa Pallikkathayil has advanced one answer by appealing to a duty to respect others’ agential interests: the possession of false beliefs constrains agency, and thus we ought not to impede the formation of true beliefs unless doing so prevents a greater constraint on someone’s agency or an otherwise impermissible end.", "questionText": "Which choice best states the main idea of the text?", "choices": ["Pallikkathayil’s argument suggests that if we have a duty to respect other people’s agential interests and if possession of false beliefs constrains agency, then we have an inviolable duty to speak truthfully.", "Pallikkathayil’s argument shows that if our intuition that circumstances may make lying permissible is correct, then it is unclear whether there are any grounds for an opposition to lying in the first place.", "One potential means of justifying opposition to lying is Pallikkathayil’s argument that we have an obligation to respect other people’s agency that entails a commitment to truthfulness except in certain circumstances.", "Many people have an intuitive sense that lying is permissible in some circumstances but lack a principled way to identify those circumstances, and Pallikkathayil’s argument may provide a means of resolving that problem."], "correctAnswer": 2, "difficulty": null}, {"qid": "q0071", "minted": "2026-10-19", "retired": false, "type": "mcq", "subject": "math", "skill": "Lines, angles, and triangles", "tags": ["src:202509asiav1:m1-q10", "fig:recrop"], "passage": null, "questionText": "In triangle {{m}}XYZ{{/m}} shown, segments {{m}}XY{{/m}} and {{m}}YZ{{/m}} each have length 128 millimeters. Which statement is sufficient to prove that all three angles in the triangle have equal measure?", "choices": ["Segment {{m}}XZ{{/m}} has length 64 millimeters.", "Segment {{m}}XZ{{/m}} has length 128 millimeters.", "Segment {{m}}XZ{{/m}} has length 256 millimeters", "Segment {{m}}XZ{{/m}} has length 384 millimeters."], "correctAnswer": 1, "difficulty": null, "figure": "data:image/png;base64,", "figureCaption": "Note: Figure not drawn to scale."}, {"qid": "q0072", "minted": "2026-10-19", "retired": false, "type": "mcq", "subject": "math", "skill": "Circles", "tags": ["src:202509asiav1:m1-q13"], "passage": null, "questionText": "Which measure, in radians, is equivalent to {{m}}(36 \\cdot 180)^{\\circ}{{/m}}?", "choices": ["{{m}}36\\pi{{/m}}", "{{m}}\\pi + 36{{/m}}", "{{m}}-\\frac{\\pi}{36}{{/m}}", "{{m}}\\pi - 36{{/m}}"], "correctAnswer": 0, "difficulty": null}, {"qid": "q0073", "minted": "2026-10-19", "retired": false, "type": "mcq", "subject": "math", "skill": "Linear functions", "tags": ["src:202509asiav1:m1-q14"], "passage": null, "questionText": "In an experiment, two solutions are combined such that the volume of the mixture increases at a constant rate of 2.6 milliliters per minute. Which of the following describes the total volume of the mixture as a function of time?", "choices": ["Increasing linear", "Decreasing linear", "Increasing exponential", "Decreasing exponential"], "correctAnswer": 0, "difficulty": null}, {"qid": "q0074", "minted": "2026-10-19", "retired": false, "type": "mcq", "subject": "math", "skill": "Lines, angles, and triangles", "tags": ["src:202509asiav1:m1-q15", "fig:recrop"], "passage": null, "questionText": "In the triangle shown, what is the value of {{m}}x{{/m}}?", "choices": ["{{m}}21{{/m}}", "{{m}}42{{/m}}", "{{m}}45{{/m}}", "{{m}}69{{/m}}"], "correctAnswer": 2, "difficulty": null, "figure": "data:image/png;base64,", "figureCaption": "Note: Figure not drawn to scale."}, {"qid": "q0075", "minted": "2026-10-19", "retired": false, "type": "mcq", "subject": "math", "skill": "Inference from sample statistics and margin of error", "tags": ["src:202509asiav1:m1-q16"], "passage": null, "questionText": "A snack company advertises that bags of pretzels produced by the company weigh, on average, 1 pound each. To test this, Sam selected at random 25 bags of pretzels produced by the company and weighed each bag. Based on his measurements, Sam estimated that for all bags of pretzels produced by the company, the average weight per bag is 1.02 pounds, with a margin of error of 0.03 pounds. For all bags of pretzels produced by the company, which of the following is the most appropriate conclusion about the average weight {{m}}w{{/m}}, in pounds, per bag?", "choices": ["{{m}}w = 1.02{{/m}}", "{{m}}0.99 \\le w \\le 1.02{{/m}}", "{{m}}0.99 \\le w \\le 1.05{{/m}}", "{{m}}1.02 \\le w \\le 1.05{{/m}}"], "correctAnswer": 2, "difficulty": null}, {"qid": "q0076", "minted": "2026-10-19", "retired": false, "type": "mcq", "subject": "math", "skill": "Linear inequalities in one or two variables", "tags": ["src:202509asiav1:m1-q17"], "passage": null, "questionText": "A rectangle has width {{m}}w{{/m}} and length {{m}}l{{/m}}. If the perimeter of the rectangle is greater than 45, which of the following inequalities must be true?", "choices": ["{{m}}w + l < 45{{/m}}", "{{m}}2w + 2l < 45{{/m}}", "{{m}}w + l > 45{{/m}}", "{{m}}2w + 2l > 45{{/m}}"], "correctAnswer": 3, "difficulty": null}, {"qid": "q0077", "minted": "2026-10-19", "retired": false, "type": "mcq", "subject": "math", "skill": "Nonlinear equations in one variable and systems of equations in two variables", "tags": ["src:202509asiav1:m1-q18"], "passage": null, "questionText": "A rectangle has a length of {{m}}x{{/m}} units and a width of {{m}}(x - 12){{/m}} units. If the rectangle has an area of 133 square units, what is the value of {{m}}x{{/m}}?", "choices": ["{{m}}7{{/m}}", "{{m}}19{{/m}}", "{{m}}26{{/m}}", "{{m}}133{{/m}}"], "correctAnswer": 1, "difficulty": null}, {"qid": "q0078", "minted": "2026-10-19", "retired": false, "type": "spr", "subject": "math", "skill": "Ratios, rates, proportional relationships, and units", "tags": ["src:202509asiav1:m1-q2"], "passage": null, "questionText": "A customer spent $12 to purchase oranges at $3 per pound. How many pounds of oranges did the customer purchase?", "correctAnswer": "4", "difficulty": null}, {"qid": "q0079", "minted": "2026-10-19", "retired": false, "type": "spr", "subject": "math", "skill": "Nonlinear functions", "tags": ["src:202509asiav1:m1-q3", "fig:recrop"], "passage": null, "questionText": "The {{m}}y{{/m}}-intercept of the graph shown is {{m}}(0, y){{/m}}. What is the value of {{m}}y{{/m}}?", "correctAnswer": "10", "difficulty": null, "figure": "data:image/png;base64,"}, {"qid": "q0080", "minted": "2026-10-19", "retired": false, "type": "mcq", "subject": "math", "skill": "Nonlinear functions", "tags": ["src:202509asiav1:m1-q4"], "passage": null, "questionText": "A biodegradable object with a mass of 36 grams started to decompose after being discarded. Each month after the object started to decompose, the remaining mass of the object was approximately 70% of the mass of the preceding month. Which function {{m}}f{{/m}} gives the approximate remaining mass, in grams, of the object {{m}}x{{/m}} months after the object started to decompose?", "choices": ["{{m}}f(x) = 36(0.3)^{x}{{/m}}", "{{m}}f(x) = 36(0.7)^{x}{{/m}}", "{{m}}f(x) = 36(1.3)^{x}{{/m}}", "{{m}}f(x) = 36(1.7)^{x}{{/m}}"], "correctAnswer": 1, "difficulty": null}, {"qid": "q0081", "minted": "2026-10-19", "retired": false, "type": "mcq", "subject": "math", "skill": "Equivalent expressions", "tags": ["src:202509asiav1:m1-q5"], "passage": null, "questionText": "Which expression is equivalent to {{m}}(8yz)(y)(3z){{/m}}?", "choices": ["{{m}}24y^{2}z^{2}{{/m}}", "{{m}}24y^{2}z{{/m}}", "{{m}}24yz{{/m}}", "{{m}}16yz{{/m}}"], "correctAnswer": 0, "difficulty": null}, {"qid": "q0082", "minted": "2026-10-19", "retired": false, "type": "mcq", "subject": "math", "skill": "One-variable data: Distributions and measures of center and spread", "tags": ["src:202509asiav1:m1-q8", "fig:recrop"], "passage": null, "questionText": "In the bar graph, which category has a frequency that is {{m}}\\frac{1}{3}{{/m}} the frequency of category E?", "choices": ["Category A", "Category B", "Category C", "Category D"], "correctAnswer": 3, "difficulty": null, "figure": "data:image/png;base64,"}, {"qid": "q0083", "minted": "2026-10-19", "retired": false, "type": "mcq", "subject": "math", "skill": "Equivalent expressions", "tags": ["src:202509asiav1:m2-q1"], "passage": null, "questionText": "Which expression is equivalent to {{m}}(8x^{2} + 5x + 9) - (8x^{2} + 3){{/m}}?", "choices": ["{{m}}6{{/m}}", "{{m}}12{{/m}}", "{{m}}5x + 6{{/m}}", "{{m}}5x + 12{{/m}}"], "correctAnswer": 2, "difficulty": null}, {"qid": "q0084", "minted": "2026-10-19", "retired": false, "type": "mcq", "subject": "math", "skill": "One-variable data: Distributions and measures of center and spread", "tags": ["src:202509asiav1:m2-q10"], "passage": "Data set A consists of 10 positive integers less than 60. The list gives 9 of the integers from data set A.{{mm}}42,46,44,42,38,39,40,47,40{{/mm}}", "questionText": "The mean of these 9 integers is 42. If the mean of data set A is an integer that is greater than 42, what is the value of the largest integer from data set A?", "choices": ["{{m}}43{{/m}}", "{{m}}47{{/m}}", "{{m}}52{{/m}}", "{{m}}59{{/m}}"], "correctAnswer": 2, "difficulty": null}, {"qid": "q0085", "minted": "2026-10-19", "retired": false, "type": "mcq", "subject": "math", "skill": "Linear functions", "tags": ["src:202509asiav1:m2-q14", "fig:recrop"], "passage": null, "questionText": "The graph of the linear function {{m}}y = f(x) + 17{{/m}} is shown. If {{m}}c{{/m}} and {{m}}d{{/m}} are positive constants, which equation could define {{m}}f{{/m}}?", "choices": ["{{m}}f(x) = -d - cx{{/m}}", "{{m}}f(x) = d + cx{{/m}}", "{{m}}f(x) = d - cx{{/m}}", "{{m}}f(x) = -d + cx{{/m}}"], "correctAnswer": 0, "difficulty": null, "figure": "data:image/png;base64,"}, {"qid": "q0086", "minted": "2026-10-19", "retired": false, "type": "spr", "subject": "math", "skill": "Area and volume", "tags": ["src:202509asiav1:m2-q18"], "passage": null, "questionText": "A rectangular region of land is divided into 88 square lots of equal area {{m}}A{{/m}}, in square units. The length of the region is 5.5 times the width of the region. If the length of the region is {{m}}x\\sqrt{A}{{/m}} units, what is the value of {{m}}x{{/m}}?", "correctAnswer": "22", "difficulty": null}, {"qid": "q0087", "minted": "2026-10-19", "retired": false, "type": "spr", "subject": "math", "skill": "Nonlinear functions", "tags": ["src:202509asiav1:m2-q19"], "passage": "{{table}}{{m}}x{{/m}} | {{m}}y{{/m}}{{row}}{{m}}25{{/m}} | {{m}}-11{{/m}}{{row}}{{m}}27{{/m}} | {{m}}9{{/m}}{{row}}{{m}}29{{/m}} | {{m}}-11{{/m}}{{/table}}", "questionText": "The table shows three values of {{m}}x{{/m}} and their corresponding values of {{m}}y{{/m}}, where {{m}}y = f(x) + 4{{/m}} and {{m}}f{{/m}} is a quadratic function. What is the {{m}}y{{/m}}-coordinate of the {{m}}y{{/m}}-intercept of the graph of {{m}}y = f(x){{/m}} in the {{m}}xy{{/m}}-plane?", "correctAnswer": "-3640", "difficulty": null}, {"qid": "q0088", "minted": "2026-10-19", "retired": false, "type": "mcq", "subject": "math", "skill": "Linear functions", "tags": ["src:202509asiav1:m2-q3"], "passage": null, "questionText": "The function {{m}}f(x) = 55.20 - 0.16x{{/m}} gives the estimated surface water temperature {{m}}f(x){{/m}}, in degrees Celsius, of Lake Superior on the {{m}}x{{/m}}th day of the year, where {{m}}220 \\le x \\le 360{{/m}}. Based on the model, what is the estimated surface water temperature, in degrees Celsius, of Lake Superior on the 298th day of the year?", "choices": ["{{m}}55.20{{/m}}", "{{m}}7.52{{/m}}", "{{m}}-0.16{{/m}}", "{{m}}-47.68{{/m}}"], "correctAnswer": 1, "difficulty": null}, {"qid": "q0089", "minted": "2026-10-19", "retired": false, "type": "mcq", "subject": "math", "skill": "Nonlinear functions", "tags": ["src:202509asiav1:m2-q4"], "passage": null, "questionText": "A company has a customer loyalty program. In January 2018, there were 300 customers enrolled in the loyalty program. For the next 24 months after January 2018, the total number of customers enrolled in the loyalty program each month was 2% greater than the total number enrolled the previous month. Which equation gives the total number of customers, {{m}}c{{/m}}, enrolled in the company’s loyalty program {{m}}m{{/m}} months after January 2018, where {{m}}m \\le 24{{/m}}?", "choices": ["{{m}}c = 300(0.02)^{m}{{/m}}", "{{m}}c = 300(1.02)^{m}{{/m}}", "{{m}}c = 300(1.2)^{m}{{/m}}", "{{m}}c = 300(2)^{m}{{/m}}"], "correctAnswer": 1, "difficulty": null}, {"qid": "q0090", "minted": "2026-10-19", "retired": false, "type": "mcq", "subject": "math", "skill": "Inference from sample statistics and margin of error", "tags": ["src:202509asiav1:m2-q6"], "passage": null, "questionText": "A machine fills bags with approximately 15 ounces of sugar. To test the accuracy of the filling process, 343 bags of sugar were selected at random and weighed. Based on the sample, it is estimated that the average weight of all bags of sugar filled by the machine in an 8-hour period is 14.88 ounces, with an associated margin of error of 0.19 ounce. Which of the following is the best interpretation of this estimate?", "choices": ["Plausible values for the average weight of all bags of sugar filled by the machine are between 14.69 ounces and 15.07 ounces.", "Plausible values for the average weight of all bags of sugar filled by the machine are less than 14.69 ounces or greater than 15.07 ounces.", "The average weight of all bags of sugar filled by the machine is greater than 14.99 ounces", "The average weight of all bags of sugar filled by the machine is less than 14.99 ounces."], "correctAnswer": 0, "difficulty": null}, {"qid": "q0091", "minted": "2026-10-19", "retired": false, "type": "mcq", "subject": "math", "skill": "Area and volume", "tags": ["src:202509asiav1:m2-q7"], "passage": null, "questionText": "A container is in the shape of a right rectangular prism that is 2.0 centimeters (cm) wide, 19.0 cm long, and 25.0 cm tall. Which of the following is closest to the number of fluid ounces that are required to completely fill the container? (Use 1.0 cubic centimeter = 0.034 fluid ounces)", "choices": ["{{m}}32{{/m}}", "{{m}}900{{/m}}", "{{m}}1{,}000{{/m}}", "{{m}}28{,}000{{/m}}"], "correctAnswer": 0, "difficulty": null}, {"qid": "q0092", "minted": "2026-10-19", "retired": false, "type": "mcq", "subject": "math", "skill": "Nonlinear equations in one variable and systems of equations in two variables", "tags": ["src:202509asiav1:m2-q9"], "passage": "{{mm}}x(x + 6) - 112 = 3x(x - 8){{/mm}}", "questionText": "What is the sum of the solutions to the given equation?", "choices": ["{{m}}2{{/m}}", "{{m}}8{{/m}}", "{{m}}14{{/m}}", "{{m}}15{{/m}}"], "correctAnswer": 3, "difficulty": null}, {"qid": "q0093", "minted": "2026-10-19", "retired": false, "type": "mcq", "subject": "rw", "skill": "Words in Context", "tags": ["src:202509asiav1:rw1-q1"], "passage": "The recovery program led by Marisel López-Flores has dramatically increased the population size of the endangered {{i}}Amazona vittata{{/i}}, the endemic parrot of Puerto Rico. Given that {{i}}A. vittata{{/i}} corresponds in physiology, behavior, and ecology to endangered {{i}}Amazona{{/i}} species elsewhere in the Caribbean, the conservation approach developed by López-Flores may be _____ across the genus.", "questionText": "Which choice completes the text with the most logical and precise word or phrase?", "choices": ["redeemable", "observable", "replicable", "comprehensible"], "correctAnswer": 2, "difficulty": null}, {"qid": "q0094", "minted": "2026-10-19", "retired": false, "type": "mcq", "subject": "rw", "skill": "Inferences", "tags": ["src:202509asiav1:rw1-q10"], "passage": "Lin-Manuel Miranda’s 2015 hip hop musical {{i}}Hamilton{{/i}} depicts historical political figure Alexander Hamilton as a self-made man who, through sheer determination, transcends his humble origins to become a key participant in the founding of the United States. This depiction of Hamilton establishes him as a compelling and well-defined protagonist but obscures other facets of the historical person’s views, namely his elitism and mistrust of the democratic politics of some of his contemporaries. In effect, the musical’s portrayal of Hamilton fails to convey the ideological complexity that a more nuanced portrayal might have suggested.", "questionText": "The text most strongly suggests that particular aspects of Hamilton’s political beliefs may have been omitted from the musical in part to achieve which effect?", "choices": ["To create an unambiguous thematic presentation of Hamilton’s life", "To suggest why certain contributions by Hamilton to US history have been overlooked", "To challenge the prevailing historical consensus about Hamilton", "To encourage modern audiences to emulate Hamilton’s politics"], "correctAnswer": 0, "difficulty": null}, {"qid": "q0095", "minted": "2026-10-19", "retired": false, "type": "mcq", "subject": "rw", "skill": "Command of Evidence (Textual)", "tags": ["src:202509asiav1:rw1-q13"], "passage": "Declining fishing technology costs and overexploitation of near-shore fishing grounds have made isolated oceanic reefs, which often lack regulatory protections, increasingly attractive to commercial and sport fishers. A team led by Octavio Aburto-Oropeza surveyed the biomass density and species composition of two isolated reefs: Alacranes, a protected (fishing prohibited) reef 135 kilometers from the Yucatan Peninsula, and Bajos del Norte, an unprotected reef 25 kilometers further out to sea. Species at the highest level of the trophic pyramid constituted 34% of the biomass at Alacranes and 10% of the biomass at Bajos del Norte. Aburto-Oropeza and colleagues attribute this difference to the two reefs’ difference in regulatory status.", "questionText": "Which finding, if true, would most directly support Aburto-Oropeza and colleagues’ explanation?", "choices": ["Total biomass at Alacranes is much greater than total biomass at Bajos del Norte, though the reefs’ biomass densities are similar.", "It is somewhat more expensive for commercial and sport fishers to reach Bajos del Norte than it is to reach Alacranes.", "Some of the species that compose the highest trophic level at Bajos del Norte are not found at Alacranes.", "Commercial and sport fishers tend to disproportionately remove species at the highest trophic level."], "correctAnswer": 3, "difficulty": null}, {"qid": "q0096", "minted": "2026-10-19", "retired": false, "type": "mcq", "subject": "rw", "skill": "Inferences", "tags": ["src:202509asiav1:rw1-q14"], "passage": "Researchers Eugeni Vidal-Tortosa and Robin Lovelace looked at the relationship between street lighting in a city and people’s willingness to ride a bicycle. Their results suggest that poor street lighting can deter new or inexperienced cyclists from riding in a city but has little effect on experienced cyclists. Therefore, increasing the number of streetlights in a city could potentially _____", "questionText": "Which choice most logically completes the text?", "choices": ["decrease the number of new or inexperienced cyclists riding in the city.", "increase the number of experienced cyclists riding in the city.", "increase the number of new or inexperienced cyclists riding in the city.", "decrease the number of experienced cyclists riding in the city."], "correctAnswer": 2, "difficulty": null}, {"qid": "q0097", "minted": "2026-10-19", "retired": false, "type": "mcq", "subject": "rw", "skill": "Inferences", "tags": ["src:202509asiav1:rw1-q15"], "passage": "Research into whether floating mats of macroalgae affect the prevalence of microphytobenthos (MPB)—benthic, or bottom-dwelling, microalgae—has produced varying results: Amber Hardison and colleagues determined that macroalgae do not impact MPB, whereas Kristina Sundbäck and colleagues observed that benthic chlorophyll concentrations (a common measure of MPB biomass) decreased in the presence of macroalgae. Hypothesizing that macroalgal mats have a negative effect on MPB biomass, Alice F. Besterman and Michael L. Pace surveyed mudflats in Curlew Bay and other coastal sites in Virginia. Because Besterman and Pace did not find a significant correlation between benthic chlorophyll concentrations and the abundance of macroalgal mats, it can be concluded that _____", "questionText": "Which choice most logically completes the text?", "choices": ["rather than inhibiting chlorophyll production in MPB, as they had hypothesized, macroalgal mats may positively affect chlorophyll production.", "their hypothesis about the relationship between macroalgae and MPB was not supported and their finding was instead consistent with that of Hardison and colleagues.", "differences between their study design and that of Sundbäck and colleagues likely explain the discrepancy in the two studies’ findings about the responses of MPB to macroalgal mats.", "although this finding was consistent with that of Sundbäck and colleagues, trends in MPB biomass are likely not a result of stresses caused by macroalgae."], "correctAnswer": 1, "difficulty": null}, {"qid": "q0098", "minted": "2026-10-19", "retired": false, "type": "mcq", "subject": "rw", "skill": "Form, Structure, and Sense", "tags": ["src:202509asiav1:rw1-q17"], "passage": "A voluntary workforce established to make improvements to public lands, parks, and forests across the US, the Civilian Conservation Corps (CCC)—though widely popular—was not without its critics. For Aldo Leopold, the CCC was implicated in what _____ “Idle CCC camps,” he wrote, “presented a widespread temptation to build new and often needless roads.”", "questionText": "Which choice completes the text so that it conforms to the conventions of Standard English?", "choices": ["did he view as unnecessary development?", "he viewed as unnecessary development?", "he viewed as unnecessary development.", "did he view as unnecessary development,"], "correctAnswer": 2, "difficulty": null}, {"qid": "q0099", "minted": "2026-10-19", "retired": false, "type": "mcq", "subject": "rw", "skill": "Boundaries", "tags": ["src:202509asiav1:rw1-q18"], "passage": "Though it was designated as mission _____ mission was actually the forty-second flight under NASA’s Space Shuttle Program.", "questionText": "Which choice completes the text so that it conforms to the conventions of Standard English?", "choices": ["STS-43. The", "STS-43, and the", "STS-43, the", "STS-43 the"], "correctAnswer": 2, "difficulty": null}, {"qid": "q0100", "minted": "2026-10-19", "retired": false, "type": "mcq", "subject": "rw", "skill": "Form, Structure, and Sense", "tags": ["src:202509asiav1:rw1-q19"], "passage": "The epic poem {{i}}The Poem of the Cid{{/i}} dates back to the 12th century. Originally _____ in Old Spanish, it has since been translated into other languages.", "questionText": "Which choice completes the text so that it conforms to the conventions of Standard English?", "choices": ["written", "is written", "was written", "had been written"], "correctAnswer": 0, "difficulty": null}, {"qid": "q0101", "minted": "2026-10-19", "retired": false, "type": "mcq", "subject": "rw", "skill": "Boundaries", "tags": ["src:202509asiav1:rw1-q20"], "passage": "Trade with neighboring civilizations contributed to the success of the Sasanian Empire, which reigned in Mesopotamia from around 224 CE to 651 CE. By supplying silk, textiles, and leather to societies that lacked these valuable _____ Sasanian Empire grew not only in wealth but also in power and influence.", "questionText": "Which choice completes the text so that it conforms to the conventions of Standard English?", "choices": ["items, the", "items. The", "items; the", "items the"], "correctAnswer": 0, "difficulty": null}, {"qid": "q0102", "minted": "2026-10-19", "retired": false, "type": "mcq", "subject": "rw", "skill": "Transitions", "tags": ["src:202509asiav1:rw1-q21"], "passage": "In his 2023 collection {{i}}The Diaspora Sonnets{{/i}}, Filipino American poet Oliver de la Paz leverages the sonnet form’s “diamond-like quality of precision,” as he describes it. The poems often adhere scrupulously to the form’s centuries-old conventions, such as its characteristic fourteen-line length. In the twelve-line poem “Diaspora Sonnet at the Feeders Before the Freeze,” _____ de la Paz playfully subverts sonnet conventions, the poem’s truncated length conveying a sense of abruptness.", "questionText": "Which choice completes the text with the most logical transition?", "choices": ["fittingly,", "by contrast,", "similarly,", "for example,"], "correctAnswer": 1, "difficulty": null}, {"qid": "q0103", "minted": "2026-10-19", "retired": false, "type": "mcq", "subject": "rw", "skill": "Rhetorical Synthesis", "tags": ["src:202509asiav1:rw1-q22"], "passage": "{{bullets}}A wind farm uses turbines to convert wind into electrical power.{{item}}Offshore wind farms tend to produce more electricity than farms on land (onshore).{{item}}Offshore wind farms tend to be more expensive to build and maintain than onshore ones.{{item}}Lake Bonney Wind Farm is an onshore wind farm in Millicent, Australia.{{/bullets}}", "questionText": "Which choice most effectively uses information from the given sentences to explain the advantages of onshore wind farms over offshore ones?", "choices": ["Like other wind farms, Lake Bonney Wind Farm in Millicent, Australia, uses turbines to turn wind power into electricity.", "Whether onshore or offshore, wind farms harness the power of wind to generate electricity.", "Millicent, Australia, is home to Lake Bonney Wind Farm.", "Though they don’t produce as much electricity as offshore wind farms, onshore farms are usually cheaper to build and maintain."], "correctAnswer": 3, "difficulty": null}, {"qid": "q0104", "minted": "2026-10-19", "retired": false, "type": "mcq", "subject": "rw", "skill": "Rhetorical Synthesis", "tags": ["src:202509asiav1:rw1-q23"], "passage": "While researching a topic, a student has taken the following notes:{{bullets}}Wilkie Collins’s mystery novel {{i}}The Woman in White{{/i}} first appeared in a London literary magazine.{{item}}The novel was published in forty weekly installments between November 1859 and August 1860.{{item}}Every installment ended with a moment of unresolved suspense.{{item}}{{i}}The Woman in White{{/i}} became extremely popular as readers eagerly anticipated the next week’s entry.{{item}}The magazine’s sales increased to a record-breaking 100,000 copies per issue.{{/bullets}}", "questionText": "The student wants to emphasize how popular {{i}}The Woman in White{{/i}} became when it was first published. Which choice most effectively uses relevant information from the notes to accomplish this goal?", "choices": ["{{i}}The Woman in White{{/i}}, a mystery novel, first appeared in a London literary magazine.", "{{i}}The Woman in White{{/i}} became so popular that sales of the magazine it appeared in increased to a record-breaking 100,000 copies per issue.", "Collins’s novel {{i}}The Woman in White{{/i}} was published in forty weekly installments between November 1859 and August 1860.", "Every installment of {{i}}The Woman in White{{/i}} ended with a moment of unresolved suspense, which led readers to eagerly anticipate the next week’s entry."], "correctAnswer": 1, "difficulty": null}, {"qid": "q0105", "minted": "2026-10-19", "retired": false, "type": "mcq", "subject": "rw", "skill": "Rhetorical Synthesis", "tags": ["src:202509asiav1:rw1-q24"], "passage": "While researching a topic, a student has taken the following notes:{{bullets}}The dinosaur ant is an insect species.{{item}}It was believed to be extinct until a living dinosaur ant was identified in Australia in 1977.{{item}}Mount Diablo buckwheat is a plant species.{{item}}It was believed to be extinct until a living Mount Diablo buckwheat was identified in the United States in 2005.{{item}}They are considered Lazarus species.{{/bullets}}“Lazarus species” is a term for living species of organisms that were once believed to be extinct.", "questionText": "The student wants to specify when the dinosaur ant was identified. Which choice most effectively uses relevant information from the notes to accomplish this goal?", "choices": ["An example of a Lazarus species was found in 2005.", "A living dinosaur ant, once believed to be extinct, was identified in 1977.", "Previously believed to be extinct, a living dinosaur ant was identified in Australia.", "Identified in the United States, a living Mount Diablo buckwheat was found in 2005."], "correctAnswer": 1, "difficulty": null}, {"qid": "q0106", "minted": "2026-10-19", "retired": false, "type": "mcq", "subject": "rw", "skill": "Rhetorical Synthesis", "tags": ["src:202509asiav1:rw1-q26"], "passage": "While researching a topic, a student has taken the following notes:{{bullets}}Stop motion animation (SMA) is a filmmaking technique that involves manipulating characters (puppets, clay figures, etc.) by hand in minute increments.{{item}}Each change in position is meticulously captured in a series of images that, when played back, give the illusion of motion.{{item}}Producer Travis Knight: “It’s a process that dates back to the dawn of cinema, with a charm and a warmth and a beauty that other forms of animation…do not have. And because you effectively get one opportunity to get it right, every shot is a high-wire act.”{{item}}Knight: SMA is “raw and it’s imperfect. It’s also undeniably human.”{{/bullets}}", "questionText": "The student wants to emphasize the aesthetic qualities of SMA by quoting Knight. Which choice most effectively uses relevant information from the notes to accomplish this goal?", "choices": ["As Knight says, “you effectively get one opportunity to get it right” when meticulously capturing the series of images that, when played back, give it the illusion of motion.", "With its puppets and clay figures, stop motion animation, Knight says, “dates back to the dawn of cinema.”", "The handmade, “imperfect” look of stop motion animation, says Knight, lends this “undeniably human” technique a “charm and a warmth and a beauty.”", "Stop motion animation is imperfect, making every shot “a high-wire act,” Knight says."], "correctAnswer": 2, "difficulty": null}, {"qid": "q0107", "minted": "2026-10-19", "retired": false, "type": "mcq", "subject": "rw", "skill": "Rhetorical Synthesis", "tags": ["src:202509asiav1:rw1-q27"], "passage": "While researching a topic, a student has taken the following notes:{{bullets}}An isthmus is a strip of land that connects two larger pieces of land across an expanse of water.{{item}}It is also known as a land bridge.{{item}}The Isthmus of Catalina Island is located in the United States.{{item}}It connects the northwestern part of Santa Catalina Island to the main part of the island.{{/bullets}}", "questionText": "The student wants to provide a specific example of an isthmus. Which choice most effectively uses relevant information from the notes to accomplish this goal?", "choices": ["One example of an isthmus is the Isthmus of Catalina Island in the United States.", "An isthmus, also known as a land bridge, is a strip of land that connects two larger pieces of land across an expanse of water.", "In the United States, the northwestern part of Santa Catalina Island is connected to the main part of the island.", "There is a land bridge in the United States."], "correctAnswer": 0, "difficulty": null}, {"qid": "q0108", "minted": "2026-10-19", "retired": false, "type": "mcq", "subject": "rw", "skill": "Words in Context", "tags": ["src:202509asiav1:rw1-q3"], "passage": "Steiger Butte Drum, a family ensemble from the Klamath Tribes of the Pacific Northwest, collaborated with composer Michael Gordon to create {{i}}Natural History{{/i}}, a work featuring traditional drumming and vocals alongside an orchestra and chorus. Steiger Butte Drum’s participation is _____ to the piece: members not only contributed to its composition but also must be included in all performances.", "questionText": "Which choice completes the text with the most logical and precise word or phrase?", "choices": ["analogous", "tangential", "subsequent", "integral"], "correctAnswer": 3, "difficulty": null}, {"qid": "q0109", "minted": "2026-10-19", "retired": true, "retiredDate": "2026-10-19", "supersededBy": "q0176", "retireReason": "superseded by the corrected text", "type": "mcq", "subject": "rw", "skill": "Text Structure and Purpose", "tags": ["src:202509asiav1:rw1-q6"], "passage": "Some researchers posit that the species inhabiting the South Pacific Island of Grande Terre belong to clades that predate the island’s split from remnants of the former supercontinent Gondwana around 80 million years ago. A study conducted by Yohan Pillon et al. found, however, that the crown age (the age of the most recent common ancestor of all living and extinct species in the clade) of the clade of {{i}}Geissois{{/i}} trees on Grande Terre is 7.3 million years; Pillon et al. further found that the crown age of the clade of {{i}}Geissois{{/i}} trees in the South Pacific generally is also approximately 7.3 million years.", "questionText": "Which choice best describes the overall structure of the text?", "choices": ["It presents a possibility that some researchers have raised, then describes a study that clarifies their reasons for doing so.", "It describes an idea that some researchers have put forward, then presents study results that are incompatible with that idea.", "It identifies a discrepancy between a hypothesis some researchers have proposed and related research findings, then explains that discrepancy.", "It explains a view some researchers have advanced, then discusses study results that led them to reconsider that view."], "correctAnswer": 1, "difficulty": null}, {"qid": "q0110", "minted": "2026-10-19", "retired": false, "type": "mcq", "subject": "rw", "skill": "Cross-Text Connections", "tags": ["src:202509asiav1:rw1-q7"], "passage": "Text 1{{br}}{{br}}In a seminal 1979 study, Daniel Kahneman and Amos Tversky presented students and college faculty from Israel, Sweden, and the United States with hypothetical questions involving financial decisions. Finding that participants’ responses indicated that losses have a greater psychological impact than equivalent gains do, the researchers formulated the concept of loss aversion, which has since informed research in fields ranging from behavioral economics to law.{{br}}{{br}}Text 2{{br}}{{br}}Fieke Harinck et al. conducted an experiment in which Dutch study participants were exposed to financial choices that involved potential losses of either relatively minor sums of money, such as 2 euros (low-stakes contexts), or more substantial sums, such as 50 euros (high-stakes contexts). The researchers concluded that only the latter contexts were associated with loss aversion.", "questionText": "Based on the texts, how would Harinck et al. (Text 2) most likely respond to Kahneman and Tversky’s finding (Text 1)?", "choices": ["By observing that researchers’ ability to assess feelings about financial decisions is contingent on gathering adequate data about gains and losses", "By contending that the attitude toward financial losses that Kahneman and Tversky observed is contingent on the magnitude of outcomes", "By disputing Kahneman and Tversky’s claim that a tendency to place excessive emphasis on financial losses accounts for the loss aversion observed in fields such as behavioral economics and law", "By agreeing that experimental results support the idea that some people tend to be more cognizant of financial losses than of gains"], "correctAnswer": 1, "difficulty": null}, {"qid": "q0111", "minted": "2026-10-19", "retired": false, "type": "mcq", "subject": "rw", "skill": "Central Ideas and Details", "tags": ["src:202509asiav1:rw1-q8"], "passage": "The following text is from Ralph Waldo Emerson’s 1841 essay “The Method of Nature.”{{br}}{{br}}{{quote}}The scholars are the priests of that thought which establishes the foundations of the earth. No matter what is their special work or profession, they stand for the spiritual interest of the world, and it is a common calamity if they neglect their post in a country where the material interest is so predominant as it is in America.{{/quote}}", "questionText": "Which choice best states the main idea of the text?", "choices": ["The habit of intellectuals of privileging ideas over material things invariably leads to tragedy.", "Scholars have played an important role in society for a much longer time than have those people who are mainly concerned with financial gain.", "In a country whose citizens are largely preoccupied with tangible gains, it is crucial that some people work to foster and preserve ideas.", "Those Americans who have some military experience will be the ones most likely to have a thorough understanding of the world."], "correctAnswer": 2, "difficulty": null}, {"qid": "q0112", "minted": "2026-10-19", "retired": false, "type": "mcq", "subject": "rw", "skill": "Central Ideas and Details", "tags": ["src:202509asiav1:rw1-q9"], "passage": "{{i}}LaRose{{/i}} is a 2016 novel by Ojibwe writer Louise Erdrich. It explores how historical events affect families on a reservation in rural North Dakota. {{i}}LaRose{{/i}} is typical of Erdrich’s work. Her writing usually focuses on portrayals of everyday life in Ojibwe communities. Yet some of her novels have fantastical plots and take place outside Ojibwe communities. For example, her 2017 novel {{i}}Future Home of the Living God{{/i}} is essentially science fiction, and the otherworldly events in its plot are set in urban Minneapolis.", "questionText": "According to the text, what is one way that {{i}}Future Home of the Living God{{/i}} differs from most of Erdrich’s work?", "choices": ["It contains very little dialogue.", "Its main characters are Ojibwe.", "It has been adapted into a movie.", "It isn’t set in a rural Ojibwe community."], "correctAnswer": 3, "difficulty": null}, {"qid": "q0113", "minted": "2026-10-19", "retired": false, "type": "mcq", "subject": "rw", "skill": "Boundaries", "tags": ["src:202509asiav1:rw2-q16"], "passage": "The world’s many geothermal power plants leverage an array of _____ the Sarulla plant uses a flash steam system that transforms high-temperature geothermal fluid into steam; in Iceland, the Reykjanes plant’s dry steam system pumps superheated steam from a reservoir; and in the US, the McGinness Hills plant’s binary cycle system uses lower-temperature geothermal fluid in conjunction with a secondary fluid.", "questionText": "Which choice completes the text so that it conforms to the conventions of Standard English?", "choices": ["technologies, in Indonesia,", "technologies: in Indonesia,", "technologies in Indonesia:", "technologies in Indonesia;"], "correctAnswer": 1, "difficulty": null}, {"qid": "q0114", "minted": "2026-10-19", "retired": false, "type": "mcq", "subject": "math", "skill": "Linear functions", "tags": ["src:202512asiav2:m1-q12"], "passage": null, "questionText": "The function {{m}}h{{/m}} is defined by {{m}}h(x) = 9x + 54{{/m}}. The graph of {{m}}y = h(x){{/m}} in the {{m}}xy{{/m}}-plane has an {{m}}x{{/m}}-intercept at {{m}}(a, 0){{/m}} and a {{m}}y{{/m}}-intercept at {{m}}(0, b){{/m}}, where {{m}}a{{/m}} and {{m}}b{{/m}} are constants. What is the value of {{m}}a+b{{/m}}?", "choices": ["{{m}}48{{/m}}", "{{m}}54{{/m}}", "{{m}}60{{/m}}", "{{m}}63{{/m}}"], "correctAnswer": 0, "difficulty": null}, {"qid": "q0115", "minted": "2026-10-19", "retired": false, "type": "mcq", "subject": "math", "skill": "Percentages", "tags": ["src:202512asiav2:m1-q15"], "passage": "During a study, scientists researched neutrinos (subatomic particles) that strike the earth’s surface. The energy, {{m}}E{{/m}}, of the neutrinos is measured in units of {{m}}10^{12}{{/m}} electron volts (TeV). The table shows the results of the scientists’ research.{{table}}Neutrino energy, {{m}}E{{/m}} (TeV) | Number of neutrinos{{row}}{{m}}E \\le 30{{/m}} | {{m}}9{{/m}}{{row}}{{m}}30 < E \\le 60{{/m}} | {{m}}13{{/m}}{{row}}{{m}}60 < E \\le 90{{/m}} | {{m}}8{{/m}}{{row}}{{m}}90 < E \\le 120{{/m}} | {{m}}2{{/m}}{{row}}{{m}}120 < E \\le 150{{/m}} | {{m}}3{{/m}}{{row}}{{m}}E > 150{{/m}} | {{m}}5{{/m}}{{/table}}", "questionText": "What percentage of these neutrinos had an energy of 90 TeV or less?", "choices": ["{{m}}20\\%{{/m}}", "{{m}}30\\%{{/m}}", "{{m}}75\\%{{/m}}", "{{m}}80\\%{{/m}}"], "correctAnswer": 2, "difficulty": null}, {"qid": "q0116", "minted": "2026-10-19", "retired": false, "type": "spr", "subject": "math", "skill": "Ratios, rates, proportional relationships, and units", "tags": ["src:202512asiav2:m1-q18"], "passage": null, "questionText": "A truck with a mass of 2,400 kilograms (kg) was first observed to travel 1,550 meters (m) in 60 seconds (s) at a constant speed. During a second observation an hour later, the same truck was observed to travel 1,150 m in 60 s at a constant speed in the same direction. What is the positive difference, in kg·m/s, between the truck’s momentum during the first observation and the truck’s momentum during the second observation?", "correctAnswer": "16000", "difficulty": null}, {"qid": "q0117", "minted": "2026-10-19", "retired": false, "type": "mcq", "subject": "math", "skill": "Nonlinear functions", "tags": ["src:202512asiav2:m1-q19"], "passage": "{{mm}}f(x) = 4x^{2} + 16x + 24{{/mm}}", "questionText": "The function {{m}}f{{/m}} is defined by the given equation. The function {{m}}h{{/m}} is defined by {{m}}h(x) = f(x) + 9{{/m}}. What is the minimum value of {{m}}h(x){{/m}}?", "choices": ["{{m}}33{{/m}}", "{{m}}17{{/m}}", "{{m}}8{{/m}}", "{{m}}7{{/m}}"], "correctAnswer": 1, "difficulty": null}, {"qid": "q0118", "minted": "2026-10-19", "retired": false, "type": "mcq", "subject": "math", "skill": "Circles", "tags": ["src:202512asiav2:m1-q20", "fig:recrop"], "passage": null, "questionText": "The circle shown has its center at {{m}}(0, 0){{/m}}. What is the value of {{m}}k{{/m}}?", "choices": ["{{m}}6{{/m}}", "{{m}}7{{/m}}", "{{m}}8{{/m}}", "{{m}}\\sqrt{55}{{/m}}"], "correctAnswer": 3, "difficulty": null, "figure": "data:image/png;base64,", "figureCaption": "Note: Figure not drawn to scale."}, {"qid": "q0119", "minted": "2026-10-19", "retired": false, "type": "mcq", "subject": "math", "skill": "Nonlinear equations in one variable and systems of equations in two variables", "tags": ["src:202512asiav2:m1-q6", "fig:recrop"], "passage": null, "questionText": "The graph of a system of an absolute value function and a linear function is shown. What is the solution {{m}}(x, y){{/m}} to this system of two equations?", "choices": ["{{m}}(0, 6){{/m}}", "{{m}}(\\frac{5}{2}, \\frac{7}{2}){{/m}}", "{{m}}(-\\frac{5}{2}, \\frac{7}{2}){{/m}}", "{{m}}(-1, 2){{/m}}"], "correctAnswer": 2, "difficulty": null, "figure": "data:image/png;base64,"}, {"qid": "q0120", "minted": "2026-10-19", "retired": false, "type": "mcq", "subject": "math", "skill": "Nonlinear functions", "tags": ["src:202512asiav2:m1-q9"], "passage": null, "questionText": "The predicted population of a city {{m}}x{{/m}} years after 1989, where {{m}}x \\le 10{{/m}}, can be modeled by the function {{m}}f(x) = 47{,}000(1.04)^{x}{{/m}}. Which of the following is the best interpretation of the statement “{{m}}f(6){{/m}} is approximately equal to {{m}}59{,}470{{/m}}” in this context?", "choices": ["6 years after 1989, the predicted population of the city is approximately 59,470 people.", "6 years after 1989, the population of the city is predicted to decrease by approximately 59,470 people.", "Every 6 years after 1989, the population of the city is predicted to decrease by approximately 59,470 people.", "Every 6 years after 1989, the population of the city is predicted to increase by approximately 59,470 people."], "correctAnswer": 0, "difficulty": null}, {"qid": "q0121", "minted": "2026-10-19", "retired": false, "type": "mcq", "subject": "math", "skill": "Two-variable data: Models and scatterplots", "tags": ["src:202512asiav2:m2-q1", "fig:recrop"], "passage": "The scatterplot shows the relationship between the number of whooping cranes, {{m}}y{{/m}}, in a certain population and the number of years since 1960, {{m}}x{{/m}}, where {{m}}0 \\le x \\le 50{{/m}}.", "questionText": "Which of the following equations is the most appropriate exponential model for the data shown in the scatterplot?", "choices": ["{{m}}y = 38(1.04)^{-x}{{/m}}", "{{m}}y = 38(1.04)^{x}{{/m}}", "{{m}}y = 286(1.04)^{-x}{{/m}}", "{{m}}y = 286(1.04)^{x}{{/m}}"], "correctAnswer": 1, "difficulty": null, "figure": "data:image/png;base64,"}, {"qid": "q0122", "minted": "2026-10-19", "retired": false, "type": "mcq", "subject": "math", "skill": "Lines, angles, and triangles", "tags": ["src:202512asiav2:m2-q10"], "passage": null, "questionText": "Triangle {{m}}ABC{{/m}} is similar to triangle {{m}}XYZ{{/m}}, where {{m}}A{{/m}} and {{m}}B{{/m}} correspond to {{m}}X{{/m}} and {{m}}Y{{/m}}, respectively. The length of each side of triangle {{m}}XYZ{{/m}} is {{m}}k{{/m}} times the length of its corresponding side in triangle {{m}}ABC{{/m}}, where {{m}}k{{/m}} is an integer greater than 1. The measure, in degrees, of angle {{m}}Z{{/m}} can be represented by the expression {{m}}5x + 26{{/m}}, where {{m}}x{{/m}} is an integer. Which of the following expressions represents the measure, in degrees, of angle {{m}}C{{/m}} for all possible values of {{m}}x{{/m}}?", "choices": ["{{m}}180 - k(5x + 26){{/m}}", "{{m}}90 - (5x + 26){{/m}}", "{{m}}k(5x + 26){{/m}}", "{{m}}5x + 26{{/m}}"], "correctAnswer": 3, "difficulty": null}, {"qid": "q0123", "minted": "2026-10-19", "retired": false, "type": "spr", "subject": "math", "skill": "Linear equations in two variables", "tags": ["src:202512asiav2:m2-q11"], "passage": "{{mm}}0.10x + 0.20y = 0.18(x+y){{/mm}}", "questionText": "The equation gives a volume {{m}}x{{/m}}, in gallons, of a 10% saltwater solution that could be mixed with a volume {{m}}y{{/m}}, in gallons, of a 20% saltwater solution to produce an 18% saltwater solution. According to this equation, what volume, in gallons, of the 20% saltwater solution could be mixed with 90.0 gallons of the 10% saltwater solution to produce an 18% saltwater solution? (Assume that the volume of the mixture is the sum of the volumes of the two solutions before they were mixed.)", "correctAnswer": "360", "difficulty": null}, {"qid": "q0124", "minted": "2026-10-19", "retired": false, "type": "spr", "subject": "math", "skill": "Nonlinear functions", "tags": ["src:202512asiav2:m2-q13"], "passage": null, "questionText": "The value of a collectible item increased by the same percentage every year between 2000 and 2007. In 2000, the value of the collectible item was $30, and in 2002, the value of the collectible item was $36.30. What was the value, in dollars, of this collectible item in 2007?", "correctAnswer": "58.46", "difficulty": null}, {"qid": "q0125", "minted": "2026-10-19", "retired": false, "type": "mcq", "subject": "math", "skill": "Equivalent expressions", "tags": ["src:202512asiav2:m2-q14"], "passage": null, "questionText": "Which expression is a factor of {{m}}x^{4} + 6ax^{2} + 9a^{2} - 16{{/m}}, where {{m}}a{{/m}} is a positive constant?", "choices": ["{{m}}x^{2} + 3a + 4{{/m}}", "{{m}}x^{2} - 3a - 4{{/m}}", "{{m}}x^{2} + 6a{{/m}}", "{{m}}x^{2} - 4a{{/m}}"], "correctAnswer": 0, "difficulty": null}, {"qid": "q0126", "minted": "2026-10-19", "retired": false, "type": "mcq", "subject": "math", "skill": "Nonlinear functions", "tags": ["src:202512asiav2:m2-q16"], "passage": "{{mm}}g(x) = \\frac{x^{2} - x - a}{x^{3} - x - b}{{/mm}}", "questionText": "The function {{m}}g{{/m}} is defined by the given equation, where {{m}}a{{/m}} and {{m}}b{{/m}} are constants. In the {{m}}xy{{/m}}-plane, the graph of {{m}}y = g(x){{/m}} passes through the point {{m}}(0, 13){{/m}}, and {{m}}g(-13) = 0{{/m}}. What is the value of {{m}}b{{/m}}?", "choices": ["{{m}}-14{{/m}}", "{{m}}-13{{/m}}", "{{m}}13{{/m}}", "{{m}}14{{/m}}"], "correctAnswer": 3, "difficulty": null}, {"qid": "q0127", "minted": "2026-10-19", "retired": false, "type": "mcq", "subject": "math", "skill": "Nonlinear equations in one variable and systems of equations in two variables", "tags": ["src:202512asiav2:m2-q17"], "passage": null, "questionText": "The equation {{m}}3|x - 2| = k{{/m}}, where {{m}}k{{/m}} is a constant, has exactly one solution. Which of the following could be the value of {{m}}\\frac{k}{3}{{/m}}?", "choices": ["{{m}}-2{{/m}} only", "{{m}}-2{{/m}} or {{m}}2{{/m}}", "{{m}}0{{/m}} only", "{{m}}2{{/m}} only"], "correctAnswer": 2, "difficulty": null}, {"qid": "q0128", "minted": "2026-10-19", "retired": false, "type": "mcq", "subject": "math", "skill": "One-variable data: Distributions and measures of center and spread", "tags": ["src:202512asiav2:m2-q18"], "passage": null, "questionText": "A zoologist observed the nests of wood ducks in an area. Each year, the zoologist recorded the number of eggs in each of the first 40 nests that were observed and created a frequency table for the data set. Which of the following frequency tables represents the data set with the smallest standard deviation?", "choices": ["{{table}}Number of eggs | Frequency{{row}}{{m}}12{{/m}} | {{m}}9{{/m}}{{row}}{{m}}13{{/m}} | {{m}}8{{/m}}{{row}}{{m}}14{{/m}} | {{m}}6{{/m}}{{row}}{{m}}15{{/m}} | {{m}}8{{/m}}{{row}}{{m}}16{{/m}} | {{m}}9{{/m}}{{/table}}", "{{table}}Number of eggs | Frequency{{row}}{{m}}12{{/m}} | {{m}}8{{/m}}{{row}}{{m}}13{{/m}} | {{m}}8{{/m}}{{row}}{{m}}14{{/m}} | {{m}}8{{/m}}{{row}}{{m}}15{{/m}} | {{m}}8{{/m}}{{row}}{{m}}16{{/m}} | {{m}}8{{/m}}{{/table}}", "{{table}}Number of eggs | Frequency{{row}}{{m}}12{{/m}} | {{m}}2{{/m}}{{row}}{{m}}13{{/m}} | {{m}}9{{/m}}{{row}}{{m}}14{{/m}} | {{m}}18{{/m}}{{row}}{{m}}15{{/m}} | {{m}}9{{/m}}{{row}}{{m}}16{{/m}} | {{m}}2{{/m}}{{/table}}", "{{table}}Number of eggs | Frequency{{row}}{{m}}12{{/m}} | {{m}}0{{/m}}{{row}}{{m}}13{{/m}} | {{m}}5{{/m}}{{row}}{{m}}14{{/m}} | {{m}}30{{/m}}{{row}}{{m}}15{{/m}} | {{m}}5{{/m}}{{row}}{{m}}16{{/m}} | {{m}}0{{/m}}{{/table}}"], "correctAnswer": 3, "difficulty": null}, {"qid": "q0129", "minted": "2026-10-19", "retired": false, "type": "spr", "subject": "math", "skill": "Nonlinear equations in one variable and systems of equations in two variables", "tags": ["src:202512asiav2:m2-q2"], "passage": "{{mm}}3x - 8y = x^{2}{{/mm}}{{mm}}3x - 8y = 16{{/mm}}", "questionText": "A solution to the given system of equations is {{m}}(x, y){{/m}}, where {{m}}x{{/m}} is positive. What is the value of {{m}}x{{/m}}?", "correctAnswer": "4", "difficulty": null}, {"qid": "q0130", "minted": "2026-10-19", "retired": false, "type": "mcq", "subject": "math", "skill": "Right triangles and trigonometry", "tags": ["src:202512asiav2:m2-q22"], "passage": null, "questionText": "An isosceles right triangle has a perimeter of {{m}}98 + 98\\sqrt{2}{{/m}} inches. What is the length, in inches, of one leg of this triangle?", "choices": ["{{m}}49{{/m}}", "{{m}}49\\sqrt{2}{{/m}}", "{{m}}98{{/m}}", "{{m}}98\\sqrt{2}{{/m}}"], "correctAnswer": 1, "difficulty": null}, {"qid": "q0131", "minted": "2026-10-19", "retired": false, "type": "mcq", "subject": "math", "skill": "Linear functions", "tags": ["src:202512asiav2:m2-q4"], "passage": null, "questionText": "A bookstore is giving away free books every day. The equation {{m}}f(x) = 210 - 14x{{/m}} gives the number of free books, {{m}}f(x){{/m}}, that remain to be given away after {{m}}x{{/m}} days. Which of the following is the best interpretation of {{m}}f(15) = 0{{/m}} in this context?", "choices": ["The bookstore has 15 free books to give away.", "The bookstore will give away 15 free books in 14 days.", "It will take 15 days to give away all the free books.", "It will take 210 days to give away 15 free books."], "correctAnswer": 2, "difficulty": null}, {"qid": "q0132", "minted": "2026-10-19", "retired": false, "type": "mcq", "subject": "math", "skill": "Systems of two linear equations in two variables", "tags": ["src:202512asiav2:m2-q5"], "passage": "{{mm}}2x + 5y = 140{{/mm}}{{mm}}-2x + 3y = 140{{/mm}}", "questionText": "The solution to the given system of equations is {{m}}(x, y){{/m}}. What is the value of {{m}}8y{{/m}}?", "choices": ["{{m}}0{{/m}}", "{{m}}35{{/m}}", "{{m}}140{{/m}}", "{{m}}280{{/m}}"], "correctAnswer": 3, "difficulty": null}, {"qid": "q0133", "minted": "2026-10-19", "retired": false, "type": "mcq", "subject": "math", "skill": "Linear equations in one variable", "tags": ["src:202512asiav2:m2-q6"], "passage": null, "questionText": "If {{m}}\\frac{7x}{2} - 18 = \\frac{35}{2} - 18{{/m}}, what is the value of {{m}}7x{{/m}}?", "choices": ["{{m}}5{{/m}}", "{{m}}10{{/m}}", "{{m}}35{{/m}}", "{{m}}42{{/m}}"], "correctAnswer": 2, "difficulty": null}, {"qid": "q0134", "minted": "2026-10-19", "retired": false, "type": "mcq", "subject": "math", "skill": "Systems of two linear equations in two variables", "tags": ["src:202512asiav2:m2-q7"], "passage": "{{mm}}x - 7y = -49{{/mm}}{{mm}}7x - 49y = 0{{/mm}}{{mm}}4x - 28y = 196{{/mm}}", "questionText": "The given system of equations is graphed in the {{m}}xy{{/m}}-plane. How many solutions {{m}}(x, y){{/m}} does the system of equations have?", "choices": ["Zero", "Exactly one", "Exactly two", "Infinitely many"], "correctAnswer": 0, "difficulty": null}, {"qid": "q0135", "minted": "2026-10-19", "retired": false, "type": "spr", "subject": "math", "skill": "Percentages", "tags": ["src:202512asiav2:m2-q8"], "passage": null, "questionText": "A car dealership has only sedans, SUVs, and minivans for sale. On Monday, 30% of the vehicles for sale were sedans and 50% were SUVs. If there were 18 sedans for sale at the dealership on Monday, how many minivans were for sale?", "correctAnswer": "12", "difficulty": null}, {"qid": "q0136", "minted": "2026-10-19", "retired": false, "type": "mcq", "subject": "rw", "skill": "Command of Evidence (Quantitative)", "tags": ["src:202512asiav2:rw1-q11"], "passage": "Minimum and Maximum Depths of Stony Coral Species in Caribbean and Indo-Pacific Waters{{table}}Species | Location | Minimum depth (meters) | Maximum depth (meters){{row}}{{i}}Isophyllia rigida{{/i}} | Caribbean | 3 | 20{{row}}{{i}}Acropora magnifica{{/i}} | Indo-Pacific | 20 | 20{{row}}{{i}}Acropora bushyensis{{/i}} | Indo-Pacific | 0 | 5{{row}}{{i}}Scolymia lacera{{/i}} | Caribbean | 10 | 80{{/table}}A marine biologist is researching four stony coral species in Caribbean and Indo-Pacific waters, focusing on sightings of these species in the shallow zone (less than 30 meters below the surface) and the mesophotic zone (30 to 150 meters below the surface). Consulting the table, she notes that the smallest maximum depth is located in _____", "questionText": "Which choice most effectively uses data from the table to complete the statement?", "choices": ["Caribbean waters in the shallow zone.", "Indo-Pacific waters in the mesophotic zone.", "Indo-Pacific waters in the shallow zone.", "Caribbean waters in the mesophotic zone."], "correctAnswer": 2, "difficulty": null}, {"qid": "q0137", "minted": "2026-10-19", "retired": false, "type": "mcq", "subject": "rw", "skill": "Command of Evidence (Textual)", "tags": ["src:202512asiav2:rw1-q12"], "passage": "{{i}}The Man-Made World: Or, Our Androcentric Culture{{/i}} is a 1911 nonfiction work by Charlotte Perkins Gilman. In the text, the author emphasizes the importance of cultivating individuals rather than comparing them: _____", "questionText": "Which quotation from {{i}}The Man-Made World: Or, Our Androcentric Culture{{/i}} most effectively illustrates the claim?", "choices": ["“A world full of healthy, happy people, each busily engaged in what [they] most enjoy doing.”", "“That every child on earth shall have right conditions to make the best growth possible to it, that every citizen, from birth to death, shall have a chance to learn all he or she can [absorb], to develop every power that is in them.”", "“We do not sadly measure the cabbage-stalk by the corn-stalk, and praise the corn for getting ahead of the cabbage—nor incite the cabbage to [imitate] the corn. We nourish both, to its best growth—and are the richer.”", "“If [the family is the unit of the state]—why not run the state on that basis?”"], "correctAnswer": 2, "difficulty": null}, {"qid": "q0138", "minted": "2026-10-19", "retired": false, "type": "mcq", "subject": "rw", "skill": "Form, Structure, and Sense", "tags": ["src:202512asiav2:rw1-q16"], "passage": "In the nineteenth century, Elizabeth Cady Stanton and Susan B. Anthony _____ for women’s right to vote in the United States.", "questionText": "Which choice completes the text so that it conforms to the conventions of Standard English?", "choices": ["having campaigned", "campaigned", "campaigning", "to campaign"], "correctAnswer": 1, "difficulty": null}, {"qid": "q0139", "minted": "2026-10-19", "retired": false, "type": "mcq", "subject": "rw", "skill": "Boundaries", "tags": ["src:202512asiav2:rw1-q20"], "passage": "Dating to around 1500, the Unicorn Tapestries are seven large tapestries depicting a unicorn hunt that hang in The Cloisters, a museum of medieval art in New York City. Attempting to explain the tapestries’ symbolism, art historian and former Cloisters head curator Margaret B. _____ that while some have interpreted the tapestries as a Christian allegory, unicorns in that era were typically featured in secular rather than religious contexts.", "questionText": "Which choice completes the text so that it conforms to the conventions of Standard English?", "choices": ["Freeman, noting", "Freeman noted", "Freeman, noted", "Freeman, who noted"], "correctAnswer": 1, "difficulty": null}, {"qid": "q0140", "minted": "2026-10-19", "retired": false, "type": "mcq", "subject": "rw", "skill": "Boundaries", "tags": ["src:202512asiav2:rw1-q21"], "passage": "The editors of {{i}}Home Ground: A Guide to the American Landscape{{/i}} turned to Stephen Graham Jones, a novelist, to craft the entry for “hueco,” a term referring to a water-retaining depression in a rock face. For “sassat,” however, the editors chose the _____ author of {{i}}Becoming Earth{{/i}}.", "questionText": "Which choice completes the text so that it conforms to the conventions of Standard English?", "choices": ["poet, Eva Saulitis", "poet Eva Saulitis", "poet, Eva Saulitis,", "poet Eva Saulitis,"], "correctAnswer": 3, "difficulty": null}, {"qid": "q0141", "minted": "2026-10-19", "retired": false, "type": "mcq", "subject": "rw", "skill": "Transitions", "tags": ["src:202512asiav2:rw1-q22"], "passage": "A research team led by Gal Badihi has discovered that chimpanzees communicate through exchanges of gestures occurring at a pace similar to that of human conversations. _____ chimpanzee gesture exchanges have short pauses of about 120 milliseconds between communications, comparable to the 200-millisecond average pause between turns in human speech.", "questionText": "Which choice completes the text with the most logical transition?", "choices": ["By contrast,", "As a result,", "Nevertheless,", "Specifically,"], "correctAnswer": 3, "difficulty": null}, {"qid": "q0142", "minted": "2026-10-19", "retired": false, "type": "mcq", "subject": "rw", "skill": "Rhetorical Synthesis", "tags": ["src:202512asiav2:rw1-q23"], "passage": "While researching a topic, a student has taken the following notes:{{bullets}}The Great Salt Lake in Utah is one of the world’s saltiest bodies of water.{{item}}The northern portion of the lake has a higher concentration of salt than the southern portion.{{item}}Green algae called {{i}}Dunaliella viridis{{/i}} live in the southern portion.{{item}}Bacteria called {{i}}Oscillatoria{{/i}} live in the southern portion.{{/bullets}}", "questionText": "The student wants to emphasize a difference between {{i}}Dunaliella viridis{{/i}} and {{i}}Oscillatoria{{/i}}. Which choice most effectively uses relevant information from the notes to accomplish this goal?", "choices": ["{{i}}Dunaliella viridis{{/i}} and {{i}}Oscillatoria{{/i}} both live in the Great Salt Lake’s southern portion.", "{{i}}Dunaliella viridis{{/i}} are green algae that live in the southern portion of the Great Salt Lake.", "The northern portion of the Great Salt Lake has a higher concentration of salt than does the southern portion.", "{{i}}Dunaliella viridis{{/i}} and {{i}}Oscillatoria{{/i}} are different types of organisms: {{i}}Dunaliella viridis{{/i}} are green algae, whereas {{i}}Oscillatoria{{/i}} are bacteria."], "correctAnswer": 3, "difficulty": null}, {"qid": "q0143", "minted": "2026-10-19", "retired": false, "type": "mcq", "subject": "rw", "skill": "Rhetorical Synthesis", "tags": ["src:202512asiav2:rw1-q24"], "passage": "While researching a topic, a student has taken the following notes:{{bullets}}Elizabeth Catlett (1915-2012) was a celebrated African American artist.{{item}}She is best known for creating sculptures and prints that explore the Black experience.{{item}}{{i}}Recognition{{/i}} is a 1970 marble sculpture by Catlett.{{item}}{{i}}Stepping Out{{/i}} is a 2000 bronze sculpture by Catlett.{{/bullets}}", "questionText": "The student wants to emphasize a difference between the two sculptures. Which choice most effectively uses relevant information from the notes to accomplish this goal?", "choices": ["Both {{i}}Recognition{{/i}} and {{i}}Stepping Out{{/i}} are sculptures by celebrated artist Elizabeth Catlett.", "Elizabeth Catlett was a celebrated artist who created prints as well as sculptures.", "{{i}}Recognition{{/i}} is a marble sculpture that Elizabeth Catlett created in 1970.", "In contrast to the sculpture {{i}}Recognition{{/i}}, which is made of marble, the sculpture {{i}}Stepping Out{{/i}} is made of bronze."], "correctAnswer": 3, "difficulty": null}, {"qid": "q0144", "minted": "2026-10-19", "retired": false, "type": "mcq", "subject": "rw", "skill": "Rhetorical Synthesis", "tags": ["src:202512asiav2:rw1-q25"], "passage": "While researching a topic, a student has taken the following notes:{{bullets}}The Mason Neck National Wildlife Refuge (NWR) is a protected natural area in Virginia.{{item}}It encompasses 2,276 acres.{{item}}The Mason Neck NWR was established to safeguard the habitat of the bald eagle, an endangered species.{{item}}The Mason Neck NWR is managed by the Us Fish & Wildlife Service.{{item}}The Us Fish & Wildlife Service limits human activities in the area.{{/bullets}}", "questionText": "The student wants to emphasize the role the US Fish & Wildlife Service plays in safeguarding the habitat of the bald eagle. Which choice most effectively uses relevant information from the notes to accomplish this goal?", "choices": ["Human activities are limited in the Mason Neck NWR, a protected natural area in Virginia.", "By limiting human activities in the Mason Neck NWR, the US Fish & Wildlife Service safeguards the habitat of the bald eagle.", "The 2,276-acre Mason Neck NWR was established to safeguard the habitat of the bald eagle, an endangered species.", "Home to the bald eagle, the Mason Neck NWR is located in Virginia, where it encompasses 2,276 acres."], "correctAnswer": 1, "difficulty": null}, {"qid": "q0145", "minted": "2026-10-19", "retired": false, "type": "mcq", "subject": "rw", "skill": "Rhetorical Synthesis", "tags": ["src:202512asiav2:rw1-q27"], "passage": "While researching a topic, a student has taken the following notes:{{bullets}}{{i}}So Long a Letter{{/i}} (1981) is an epistolary novel by Senegalese author Mariama Bâ.{{item}}Epistolary novels are novels written primarily as a series of fictional documents.{{item}}These documents can be letters, journal entries, newspaper clippings, and more.{{item}}{{i}}So Long a Letter{{/i}} consists primarily of letters.{{item}}The letters are sent between a widow named Ramatoulaye and her best friend, Aissatou.{{/bullets}}", "questionText": "The student wants to provide an example of an epistolary novel. Which choice most effectively uses relevant information from the notes to accomplish this goal?", "choices": ["Consisting primarily of letters sent between a widow named Ramatoulaye and her best friend, Aissatou, Mariama Bâ’s {{i}}So Long a Letter{{/i}} is an epistolary novel.", "An epistolary novel is a novel written primarily as a series of fictional documents, such as letters, journal entries, or newspaper clippings.", "It was Mariama Bâ who published the novel {{i}}So Long a Letter{{/i}} in 1981.", "In 1981, Senegalese author Mariama Bâ published a novel of letters sent between a widow named Ramatoulaye and her best friend, Aissatou."], "correctAnswer": 0, "difficulty": null}, {"qid": "q0146", "minted": "2026-10-19", "retired": false, "type": "mcq", "subject": "rw", "skill": "Text Structure and Purpose", "tags": ["src:202512asiav2:rw1-q7"], "passage": "Lennox Brown’s powerful play {{i}}A Ballet Behind the Bridge{{/i}} was produced in 1972 by the groundbreaking Negro Ensemble Company (NEC). NEC cofounder Robert Hooks, an actor, producer, and activist, had met actor and playwright Douglas Turner Ward while they were performing in a 1960 touring production of Lorraine Hansberry’s play {{i}}A Raisin in the Sun{{/i}}. Together, they envisioned a theater company that would nurture and showcase the work of Black theater professionals. {{u}}Since NEC’s founding in 1967, its workshops and performances have given Black playwrights, including Brown, a forum for their compelling stories.{{/u}}", "questionText": "Which choice best describes the function of the underlined sentence in the text as a whole?", "choices": ["It explains the circumstances that led to the formation of the theater company discussed in the text.", "It emphasizes the ongoing significance of the theater company discussed in the text.", "It illustrates the widespread influence of a play discussed earlier in the text.", "It provides additional information about a person mentioned in the text."], "correctAnswer": 1, "difficulty": null}, {"qid": "q0147", "minted": "2026-10-19", "retired": false, "type": "mcq", "subject": "rw", "skill": "Inferences", "tags": ["src:202512asiav2:rw1-q9"], "passage": "Given the immense scope of space, the search for extraterrestrial life is almost necessarily concentrated on the exoplanets deemed to have the most plausible chance of success—typically, atmosphere-bearing terrestrial planets orbiting within a certain range of their stars (termed the habitable zone). Claiming that Earth experienced a long transition from single-lid to plate tectonics that accelerated the emergence and evolution of complex organisms, researchers Robert J. Stern and Taras V. Gerya hold that consideration of tectonics, an often overlooked factor, could help further narrow the search for advanced extraterrestrial species.", "questionText": "Based on the text, what do Stern and Gerya most likely believe about the development of complex life on exoplanets?", "choices": ["It is probably more dependent on the presence of plate tectonics than on orbital distance from a host star or the presence of an atmosphere.", "It is unlikely unless the transition from single-lid to plate tectonics occurs before the acquisition of a lasting atmosphere.", "It is more likely to occur if habitable zone planets with atmospheres transition from single-lid to plate tectonics late in their history than if they transition early in their history.", "It is more likely to occur on habitable zone planets with atmospheres and plate tectonics than on otherwise similar planets that lack plate tectonics."], "correctAnswer": 3, "difficulty": null}, {"qid": "q0148", "minted": "2026-10-19", "retired": false, "type": "mcq", "subject": "rw", "skill": "Words in Context", "tags": ["src:202512asiav2:rw2-q1"], "passage": "Analysis of preserved plants cataloged in the Southeast Regional Network of Expertise and Collections indicates that rising temperatures correlate with earlier leaf production, but such specimens represent only brief moments in plants’ overall development. _____ this research with studies involving live plants would enable a fuller understanding of how these observed changes affect plant fitness.", "questionText": "Which choice completes the text with the most logical and precise word or phrase?", "choices": ["Categorizing", "Complementing", "Foregrounding", "Anticipating"], "correctAnswer": 1, "difficulty": null}, {"qid": "q0149", "minted": "2026-10-19", "retired": false, "type": "mcq", "subject": "rw", "skill": "Command of Evidence (Textual)", "tags": ["src:202512asiav2:rw2-q11"], "passage": "Most Native languages belong to language families, or groups of languages whose similarities in vocabulary and grammar suggest shared descent from a single language spoken long ago. In contrast, the language spoken by the Esselen people in a mountainous area of Central California was an isolate, or a language with no demonstrated relationship to other languages. Isolates are more prevalent in mountainous regions than elsewhere, likely because challenging terrain inhibits the geographical expansion of language families. {{u}}Yet it is clear that geographical barriers on their own cannot fully explain this aspect of the distribution of Indigenous languages in California and elsewhere in the present-day United States.{{/u}}", "questionText": "Which statement, if true, would most directly support the claim in the underlined sentence?", "choices": ["In mountainous regions of the western US, isolate-speaking peoples historically met most of their food needs through foraging, hunting, and fishing rather than intensive farming.", "Esselen and other isolates spoken in mountainous regions of California tend to contain many more terms describing features of mountainous terrain than nonisolate languages from relatively flat regions of California do.", "Shoshone, a language in the Uto-Aztecan family, was originally spoken in a vast expanse of Idaho, Nevada, Oregon, and Wyoming—a region whose mountainousness rivals that of the homeland of the Esselen people.", "Although Native languages in non-mountainous areas of California tend to belong to language families, those families do not necessarily share common linguistic ancestry."], "correctAnswer": 2, "difficulty": null}, {"qid": "q0150", "minted": "2026-10-19", "retired": false, "type": "mcq", "subject": "rw", "skill": "Inferences", "tags": ["src:202512asiav2:rw2-q14"], "passage": "In 2003, the US state of Florida enacted rate stability regulations (RSRs), constraining insurance companies’ latitude to raise premiums (the periodic fees policyholders pay to maintain insurance policies) after policies are in effect, RSRs are effective at protecting existing policyholders from price volatility, but Naoki Aizawa and Ami Ko note that since dynamic pricing of premiums is an important risk-mitigation tool for insurers, RSRs may lead some insurers to scale back or entirely cease selling new policies in the affected market, thereby reducing the competitive pressure that typically restrains premium prices for new policies. Thus, Florida’s RSRs may _____", "questionText": "Which choice most logically completes the text?", "choices": ["benefit policyholders at the expense of nonpolicyholders seeking to acquire policies.", "reduce premium price volatility once policies are in effect but increase risks for policyholders.", "prevent large increases in premium prices for new policies despite leading to fewer insurers offering such policies in the affected market.", "be more advantageous for insurers than they are for either current or prospective policyholders."], "correctAnswer": 0, "difficulty": null}, {"qid": "q0151", "minted": "2026-10-19", "retired": false, "type": "mcq", "subject": "rw", "skill": "Boundaries", "tags": ["src:202512asiav2:rw2-q17"], "passage": "“Streetwide and bitter as hope / strewn between El Salvador and San Francisco.” These lines are from a poem by Chicano _____ whose early career as a campesino informs the dialogue on Mexican American politics and identity that unfolds in his work.", "questionText": "Which choice completes the text so that it conforms to the conventions of Standard English?", "choices": ["writer Juan Felipe Herrera", "writer, Juan Felipe Herrera", "writer, Juan Felipe Herrera,", "writer Juan Felipe Herrera,"], "correctAnswer": 3, "difficulty": null}, {"qid": "q0152", "minted": "2026-10-19", "retired": false, "type": "mcq", "subject": "rw", "skill": "Boundaries", "tags": ["src:202512asiav2:rw2-q19"], "passage": "Among the small magazines animating London’s vibrant literary scene in the early twentieth century was _____ by Dora Marsden and featuring poetry by Amy Lowell, Allen Upward, and William Carlos Williams; essays by Muriel Ciolkowska and Huntly Carter; and fiction by Rebecca West, this magazine publicized the work of influential avant-garde writers and artists of the day.", "questionText": "Which choice completes the text so that it conforms to the conventions of Standard English?", "choices": ["the {{i}}New Freewoman{{/i}}, edited", "the {{i}}New Freewoman{{/i}}; edited", "the {{i}}New Freewoman{{/i}}. Edited", "the {{i}}New Freewoman{{/i}} edited"], "correctAnswer": 2, "difficulty": null}, {"qid": "q0153", "minted": "2026-10-19", "retired": false, "type": "mcq", "subject": "rw", "skill": "Words in Context", "tags": ["src:202512asiav2:rw2-q2"], "passage": "In the Metropolitan Museum of Art’s Costume Institute’s innovative multisensory exhibit of garments and accessories spanning four centuries, an emphasis on the _____ of fashion was conveyed both by the exhibit’s theme of perpetual renewal in nature and, more subtly, by its scientific re-creations of ephemeral elements (like a fragrance worn with a dress more than a century ago).", "questionText": "Which choice completes the text with the most logical and precise word or phrase?", "choices": ["definitiveness", "partiality", "superficiality", "transience"], "correctAnswer": 3, "difficulty": null}, {"qid": "q0154", "minted": "2026-10-19", "retired": false, "type": "mcq", "subject": "rw", "skill": "Form, Structure, and Sense", "tags": ["src:202512asiav2:rw2-q20"], "passage": "The extensive impact that selenium nanoparticles (SeNPs) have had on medicine belies their minuscule size, the nanoparticles typically _____ from only 10 to 45 billionths of a meter.", "questionText": "Which choice completes the text so that it conforms to the conventions of Standard English?", "choices": ["can range", "will range", "ranging", "range"], "correctAnswer": 2, "difficulty": null}, {"qid": "q0155", "minted": "2026-10-19", "retired": false, "type": "mcq", "subject": "rw", "skill": "Transitions", "tags": ["src:202512asiav2:rw2-q23"], "passage": "On a chilly spring morning in a Virginia park, as sunlight crested the treetops, Kathrin Swoboda raised her Nikon D500 camera and captured an image that would win the Grand Prize in the 2019 Audubon Photography Awards: a red-winged blackbird, exhaling what appeared to be rings of smoke. _____ the “smoke” was actually the blackbird’s breath hitting the cold morning air as the bird sang.", "questionText": "Which choice completes the text with the most logical transition?", "choices": ["Therefore,", "Furthermore,", "For example,", "Of course,"], "correctAnswer": 3, "difficulty": null}, {"qid": "q0156", "minted": "2026-10-19", "retired": false, "type": "mcq", "subject": "rw", "skill": "Transitions", "tags": ["src:202512asiav2:rw2-q25"], "passage": "Followers of the philosopher Hegel argue that sound reasoning must be forged by the tension of the dialectic, which is to say, each stage of a thought’s progression should contain within it the very seeds of its negation. _____ Hegelians resist the notion that logic is weakened by contradiction, believing the latter to be a necessary precursor to the former.", "questionText": "Which choice completes the text with the most logical transition?", "choices": ["However,", "Still,", "Finally,", "Accordingly,"], "correctAnswer": 3, "difficulty": null}, {"qid": "q0157", "minted": "2026-10-19", "retired": false, "type": "mcq", "subject": "rw", "skill": "Rhetorical Synthesis", "tags": ["src:202512asiav2:rw2-q26"], "passage": "While researching a topic, a student has taken the following notes:{{bullets}}Extravehicular activities (EVAs) are activities performed outside a spacecraft by astronauts in outer space.{{item}}EVAs are also known as spacewalks.{{item}}Andrew Morgan is a US astronaut who has performed 7 spacewalks.{{item}}The total time of Morgan’s spacewalks was 45 hours and 48 minutes.{{item}}Douglas Wheelock is a US astronaut who has performed 6 spacewalks.{{item}}The total time of Wheelock’s spacewalks was 43 hours and 30 minutes.{{/bullets}}", "questionText": "The student wants to emphasize a similarity between the astronauts Morgan and Wheelock. Which choice most effectively uses relevant information from the notes to accomplish this goal?", "choices": ["Morgan and Wheelock have each performed multiple spacewalks.", "EVAs, also known as spacewalks, are activities done by astronauts outside a spacecraft.", "Morgan has performed spacewalks, but Wheelock has performed EVAs.", "Wheelock has spent less time performing spacewalks than Morgan has."], "correctAnswer": 0, "difficulty": null}, {"qid": "q0158", "minted": "2026-10-19", "retired": false, "type": "mcq", "subject": "rw", "skill": "Words in Context", "tags": ["src:202512asiav2:rw2-q3"], "passage": "Highly skilled specialists can often distinguish modern forgeries from authentic historical paintings on the basis of subtle deviations from the historical artist’s style and techniques, but since no painter is truly _____, scientific tests of paints, canvases, and frames are sometimes used to establish whether a painting could have been made during a given historical artist’s lifetime.", "questionText": "Which choice completes the text with the most logical and precise word or phrase?", "choices": ["autonomous", "inimitable", "contemporaneous", "prolific"], "correctAnswer": 1, "difficulty": null}, {"qid": "q0159", "minted": "2026-10-19", "retired": false, "type": "mcq", "subject": "rw", "skill": "Text Structure and Purpose", "tags": ["src:202512asiav2:rw2-q5"], "passage": "The following text is from Rachel Heng’s 2023 novel {{i}}The Great Reclamation{{/i}}. Ah Boon is fishing off the coast of Singapore.{{br}}{{br}}{{quote}}When he pulled up the nets, they contained only one kind of fish—{{u}}black pomfrets{{/u}}, the flat diamonds of their bodies slick in the morning light. This uniformity did not surprise him, over the years, he’d learned that the waters here were temperamental. They could be relied upon for a good catch, but from time to time threw up only {{u}}prawns or squid{{/u}}, and other times {{u}}colorful varieties of fish{{/u}} that weren’t even supposed to be found in this region. He’d grown to accept the unpredictability, embracing it as a game to be played, like the reading of tea leaves or the grooves of a palm.{{/quote}}", "questionText": "Taken together, the three underlined portions most clearly serve which function in the text as a whole?", "choices": ["They illustrate the changeable nature of the fishing grounds where Ah Boon is.", "They emphasize the wide variety of sea creatures that Ah Boon has caught on this particular fishing trip.", "They underscore Ah Boon’s lack of surprise at seeing sea creatures that aren’t usually found in the region.", "They provide examples of what Ah Boon most frequently catches in the area."], "correctAnswer": 0, "difficulty": null}, {"qid": "q0160", "minted": "2026-10-19", "retired": false, "type": "mcq", "subject": "rw", "skill": "Inferences", "tags": ["src:202512asiav3:rw2-q14"], "passage": "In 2002, the US state of Texas enacted rate stability regulations (RSRs), constraining insurance companies’ latitude to raise premiums (the periodic fees policyholders pay to maintain insurance policies) after policies are in effect, RSRs are effective at protecting existing policyholders from price volatility, but Naoki Aizawa and Ami Ko note that since dynamic pricing of premiums is an important risk-mitigation tool for insurers, RSRs may lead some insurers to scale back or entirely cease selling new policies in the affected market, thereby reducing the competitive pressure that typically restrains premium prices for new policies. Thus, Texas’s RSRs may _____", "questionText": "Which choice most logically completes the text?", "choices": ["prevent large increases in premium prices for new policies despite leading to fewer insurers offering such policies in the affected market.", "reduce premium price volatility once policies are in effect but increase risks for policyholders.", "benefit policyholders at the expense of nonpolicyholders seeking to acquire policies.", "be more advantageous for insurers than they are for either current or prospective policyholders."], "correctAnswer": 2, "difficulty": null}, {"qid": "q0161", "minted": "2026-10-19", "retired": false, "type": "mcq", "subject": "rw", "skill": "Form, Structure, and Sense", "tags": ["src:202408usv3:rw1-q15"], "passage": "In 1989, Missouri _____ official fossil: the {{i}}Eperisocrinus missouriensis{{/i}}, which is a Carboniferous period marine animal.", "questionText": "Which choice completes the text so that it conforms to the conventions of Standard English?", "choices": ["lawmaker’s designated the states", "lawmakers designated the state’s", "lawmaker’s designated the state’s", "lawmakers designated the states"], "correctAnswer": 1, "difficulty": null}, {"qid": "q0162", "minted": "2026-10-19", "retired": false, "type": "mcq", "subject": "rw", "skill": "Command of Evidence (Textual)", "tags": ["src:202408usv3:rw2-q11"], "passage": "Water flowing around an obstruction creates vortices (swirls) that vary in size with the obstruction’s size and position, and fish sense these vortices in order to navigate around the obstructions. Using models of three fish-head shapes—narrow (low ratio of width to length), intermediate, and wide (high ratio of width to length)—Yuzo R. Yanagisuru, Otar Akanyeti, and James C. Liao showed that as vortex size increases, pressure fluctuations at the snout increase for narrow-headed and intermediate-headed fish but remain low for wide-headed fish. A second research team has therefore hypothesized that in low visibility a fish will be more likely to avoid an obstruction when the associated pressure fluctuations at the fish’s snout are greater.", "questionText": "Which finding, if true, would most directly challenge the second research team’s hypothesis?", "choices": ["A study using obstructions that created large vortices in low-visibility conditions found that the {{i}}Synodontis macropunctata{{/i}}, which has a relatively wide head, bumped into less than half of the obstructions.", "A study using obstructions that created large vortices in low-visibility conditions found that the intermediate-headed dusky smooth-hound ({{i}}Mustelus canis{{/i}}) bumped into the obstructions just as often as the wide-headed {{i}}Synodontis macropunctata{{/i}} did.", "A study using obstructions that created large vortices in low-visibility conditions found that the wide-headed {{i}}Synodontis macropunctata{{/i}} bumped into obstructions more often than the intermediate-headed dusky smooth-hound ({{i}}Mustelus canis{{/i}}) did.", "A study using obstructions that created large vortices in low-visibility conditions found that some specimens of the intermediate-headed dusky smooth-hound ({{i}}Mustelus canis{{/i}}) bumped into the obstructions more often than others did."], "correctAnswer": 1, "difficulty": null}, {"qid": "q0163", "minted": "2026-10-19", "retired": false, "type": "mcq", "subject": "rw", "skill": "Command of Evidence (Quantitative)", "tags": ["src:202408usv3:rw2-q12", "fig:recrop"], "passage": "In a study of the evolution of DptA and DptB—Diptericin genes encoding antimicrobial peptides that combat pathogens and foster beneficial microbes in fruit flies ({{i}}Drosophila{{/i}})—researchers assessed {{i}}Drosophila melanogaster{{/i}} resistance to pathogenic infections by {{i}}Providencia rettgeri{{/i}} and {{i}}Acetobacter sicerae{{/i}}, bacteria common in the flies’ environments. Subjects included flies identified by mutations silencing DptA, DptB, or both DptA and DptB (termed types A, B, and AB, respectively). In conjunction with the observation that resistance to {{i}}P. rettgeri{{/i}} correlates with DptA activity but is not significantly affected by DptB activity, data in the graph of survival rates post-{{i}}A. sicerae{{/i}} infection suggest that _____", "questionText": "Which completion of the text is best supported by data in the graph?", "choices": ["DptA confers defense against {{i}}A. sicerae{{/i}} regardless of the presence of DptB.", "DptB may have developed as a specific defense against {{i}}A. sicerae{{/i}}.", "DptB protects against only one bacteria species, whereas DptA protects against multiple species.", "defense against {{i}}A. sicerae{{/i}} is strongest when both DptA and DptB are present."], "correctAnswer": 1, "difficulty": null, "figure": "data:image/png;base64,"}, {"qid": "q0164", "minted": "2026-10-19", "retired": false, "type": "mcq", "subject": "rw", "skill": "Boundaries", "tags": ["src:202408usv3:rw2-q21"], "passage": "The Organisation for Economic Co-operation and Development (OECD) tracks comparative price list data for its thirty-eight member countries. According to this data, in July 2021, a “basket” of goods and services priced at 100 US dollars (USD) in the United States would have cost 105 USD in fellow OECD member _____", "questionText": "Which choice completes the text so that it conforms to the conventions of Standard English?", "choices": ["nation—Finland.", "nation: Finland.", "nation, Finland.", "nation Finland."], "correctAnswer": 3, "difficulty": null}, {"qid": "q0165", "minted": "2026-10-19", "retired": false, "type": "mcq", "subject": "rw", "skill": "Boundaries", "tags": ["src:202506asiav1:rw1-q20"], "passage": "Exemplars of Stigler’s law _____ there is the Argand diagram; in astronomy, the Cassegrain reflector; and in physics, the Fermi paradox. All the aforementioned share the trait of being named after individuals who were not their initial discoverers or inventors.", "questionText": "Which choice completes the text so that it conforms to the conventions of Standard English?", "choices": ["abound, in mathematics,", "abound in mathematics:", "abound: in mathematics,", "abound in mathematics;"], "correctAnswer": 2, "difficulty": null}, {"qid": "q0166", "minted": "2026-10-19", "retired": false, "type": "mcq", "subject": "rw", "skill": "Text Structure and Purpose", "tags": ["src:202506asiav1:rw1-q7"], "passage": "Allison Q. Byrne and colleagues relied on historical DNA (hDNA)—genomic data incidentally preserved in specimens housed in collections such as those at the Smithsonian National Museum of Natural History—to investigate the evolutionary origins of a pathogen affecting amphibians. Although this approach can yield many insights about the biological past, it remains a relatively underutilized resource in part because hDNA is often to some extent degraded, a situation not easily remediable under current methodological paradigms and with extant DNA extraction and analysis technologies.", "questionText": "Which choice best describes the overall structure of the text?", "choices": ["It presents a scientific study that relied on a particular approach, then describes a barrier to the widespread adoption of that approach.", "It evaluates a research methodology used in a particular study, then explains how scientists may overcome difficulties inherent to that methodology.", "It summarizes the findings of a scientific study, then discusses the possibility of other researchers replicating those findings in future studies.", "It exemplifies a common method of genomic data analysis, then details the difficulties in adapting that method to new circumstances."], "correctAnswer": 0, "difficulty": null}, {"qid": "q0167", "minted": "2026-10-19", "retired": false, "type": "mcq", "subject": "rw", "skill": "Inferences", "tags": ["src:202506asiav1:rw2-q14"], "passage": "The single origin hypothesis of iron metallurgy posits that the craft originated in Anatolia (West Asia) circa 2200-2000 BCE before diffusing to other parts of the world, including Africa. Some proponents of the hypothesis argue that iron production technologies first arrived in North Africa through Carthage, where the earliest evidence of ironworking dates to approximately 800-600 BCE, before these technologies spread to sub-Saharan Africa over the following centuries. However, excavation of multiple sites on the Adamawa plateau in Central Africa conducted by Etienne Zangato and Augustin Holl uncovered evidence of iron workshops that may have been in operation as late as 900-750 BCE in Gbabari and as early as 2300-1900 BCE in Ôboui and Gbatoro. These findings suggest that _____", "questionText": "Which choice most logically completes the text?", "choices": ["iron production may have originated in Anatolia much earlier than the available evidence currently indicates.", "iron production technologies were likely transmitted from Anatolia to Central Africa via an alternate route than the one suggested by some proponents of the single origin hypothesis.", "iron production technologies found in Gbabari likely derived directly from technologies transmitted from Anatolia, but those found in Ôboui and Gbatoro did not.", "iron production may have developed independently and relatively simultaneously in Anatolia and parts of Central Africa."], "correctAnswer": 3, "difficulty": null}, {"qid": "q0168", "minted": "2026-10-19", "retired": false, "type": "mcq", "subject": "rw", "skill": "Inferences", "tags": ["src:202506asiav1:rw2-q15"], "passage": "Exclusively inhabiting tropical countries such as Ghana, wild chimpanzees lack adaptations to seasonal variations in ultraviolet B (UVB) irradiance from sunlight; since UVB exposure enables vertebrates to synthesize vitamin D, Sophie Moittié and colleagues studied zoo chimpanzees in Spain and other mid-latitude countries to see how vitamin D levels are affected by the seasonal variations in UVB irradiance that occur in those locations. They found that chimpanzees’ vitamin D levels were significantly lower in autumn than in summer and appeared unaffected by oral supplementation of vitamin D administered by zookeepers. Moittié and colleagues point out, however, that supplementation was rare, highly varied, and poorly tracked and therefore _____", "questionText": "Which choice most logically completes the text?", "choices": ["the effect of supplemental vitamin D on zoo chimpanzees in Spain and other mid-latitude countries can more clearly be observed in summer than in autumn.", "the possibility that zoo chimpanzees in Spain and other mid-latitude countries would benefit from supplemental vitamin D during autumn cannot be excluded.", "vitamin D levels in zoo chimpanzees in Spain and other mid-latitude countries may be higher during autumn than Moittié and colleagues’ data appear to indicate.", "differences in vitamin D supplementation likely explain more of the difference in vitamin D levels across zoo chimpanzees in Spain and other mid-latitude countries than seasonal differences in UVB irradiation do."], "correctAnswer": 1, "difficulty": null}, {"qid": "q0169", "minted": "2026-10-19", "retired": false, "type": "mcq", "subject": "rw", "skill": "Boundaries", "tags": ["src:202506asiav1:rw2-q19"], "passage": "Scheme is referred to as a compiled programming language because it typically incorporates a compiler—a tool that translates lines of code into executable commands. Compiling isn’t exclusive to certain programming _____ any language can incorporate this tool.", "questionText": "Which choice completes the text so that it conforms to the conventions of Standard English?", "choices": ["languages; however,", "languages, however,", "languages. However,", "languages, however;"], "correctAnswer": 3, "difficulty": null}, {"qid": "q0170", "minted": "2026-10-19", "retired": false, "type": "mcq", "subject": "rw", "skill": "Boundaries", "tags": ["src:202506asiav1:rw2-q20"], "passage": "Reena Esmail, an Indian American classical composer, incorporates Indian musical elements into her work. Esmail’s 2013 violin and piano composition {{i}}Jhula-Jhule{{/i}} intertwines the melodies of two Indian folk _____ in {{i}}TaReKiTa{{/i}}, a 2016 choral composition, Esmail features onomatopoeic notes imitating the sounds of the tabla, a type of Indian drum.", "questionText": "Which choice completes the text so that it conforms to the conventions of Standard English?", "choices": ["songs, for instance,", "songs. For instance, while", "songs; for instance,", "songs, for instance, while"], "correctAnswer": 3, "difficulty": null}, {"qid": "q0171", "minted": "2026-10-19", "retired": false, "type": "mcq", "subject": "rw", "skill": "Transitions", "tags": ["src:202506asiav1:rw2-q23"], "passage": "In the early 1900s, sculptor and collector Gerbude Whitney was one of the foremost champions of avant-garde art, helping many US avant-garde artists gain publicity and exposure. _____ Whitney offered to donate more than 500 avant-garde works to be displayed at a leading New York museum, but the museum said no—so she opened her own, the Whitney Museum of American Art.", "questionText": "Which choice completes the text with the most logical transition?", "choices": ["To this end,", "In other words,", "In contrast,", "Granted,"], "correctAnswer": 0, "difficulty": null}, {"qid": "q0172", "minted": "2026-10-19", "retired": false, "type": "mcq", "subject": "rw", "skill": "Central Ideas and Details", "tags": ["src:202506asiav1:rw2-q8"], "passage": "The blue shark and the striped marlin are ectothermic (cold-blooded) fish, whereas the salmon shark and the Pacific bluefin tuna are regional endotherms—they retain metabolic heat resulting in body temperatures above the ambient water temperature. Unlike those of ectotherms, regional endotherms’ hearts have a relatively high proportion (greater than 30%) of compact myocardial tissue, which is needed to maintain these animals’ blood pressure. In a 2023 study, Haley R. Dolton and colleagues found that basking sharks—planktivorous filter-feeders that were classified as full ectotherms at the time—have hearts consisting of 47% compact myocardial tissue, thereby undermining that classification.", "questionText": "According to the text, which choice most accurately describes the importance of the percentage of compact myocardial tissue in the basking shark’s heart?", "choices": ["It is insufficient to establish that the basking shark should be categorized as Dolton and colleagues suggest.", "It is higher than that of the salmon shark, a regional endotherm, despite the basking shark being a full ectotherm.", "It is higher than that of the Pacific bluefin tuna, a regional endotherm, which calls into question the basking shark’s status as a regional endotherm.", "It is, by itself, sufficient to invalidate how the basking shark has been categorized in the past."], "correctAnswer": 3, "difficulty": null}, {"qid": "q0173", "minted": "2026-10-19", "retired": false, "type": "spr", "subject": "math", "skill": "Linear equations in one variable", "tags": ["src:202509asiav1:m1-q11"], "passage": "{{mm}}f(r) = 15 + 3r{{/mm}}", "questionText": "The function {{m}}f{{/m}} represents the total cost, in dollars, of attending a carnival when {{m}}r{{/m}} rides are ridden. How many rides can be ridden for a total cost of $51?", "correctAnswer": "12", "difficulty": null}, {"qid": "q0174", "minted": "2026-10-19", "retired": false, "type": "spr", "subject": "math", "skill": "Area and volume", "tags": ["src:202509asiav1:m1-q9"], "passage": null, "questionText": "Each side of a triangle has a length of 27. What is the perimeter of this triangle?", "correctAnswer": "81", "difficulty": null}, {"qid": "q0175", "minted": "2026-10-19", "retired": false, "type": "mcq", "subject": "rw", "skill": "Text Structure and Purpose", "tags": ["src:202509asiav1:rw1-q4"], "passage": "The following text is adapted from Susan Glaspell’s 1917 play {{i}}The People{{/i}}. Oscar, a writer at a newspaper called {{i}}The People{{/i}}, is writing at a table when a woman enters the office to speak to the editor.{{br}}{{br}}{{quote}}THE WOMAN: This {{i}}is{{/i}} the office of {{i}}The People{{/i}}?{{br}}{{br}}OSCAR: Um-hum.{{br}}{{br}}THE WOMAN: ({{i}}Excitedly{{/i}}.) I came to see the author of those wonderful words.{{br}}{{br}}{{u}}OSCAR: ({{i}}Rising{{/i}}.) Which wonderful words?{{/u}}{{br}}{{br}}THE WOMAN: About moving toward the beautiful distances.{{br}}{{br}}OSCAR: ({{i}}Loses interest and returns to his writing{{/i}}.): Oh. Those are Mr. Wills’ wonderful words.{{br}}{{br}}THE WOMAN: Could I see him?{{br}}{{br}}OSCAR: He isn’t here yet. He’s just back from California. Won’t be at the office till a little later.{{/quote}}", "questionText": "Which choice best states the function of the underlined portion in the text as a whole?", "choices": ["To suggest that Oscar is annoyed that the woman’s visit has interrupted his work", "To indicate that Oscar had been expecting the woman to come to the office", "To show Oscar’s brief hope that the woman is fond of his writing", "To depict Oscar as a polite and professional representative of the newspaper"], "correctAnswer": 2, "difficulty": null}, {"qid": "q0176", "minted": "2026-10-19", "retired": false, "type": "mcq", "subject": "rw", "skill": "Text Structure and Purpose", "tags": ["src:202509asiav1:rw1-q6"], "passage": "Some researchers posit that the species inhabiting the South Pacific island of Grande Terre belong to clades that predate the island’s split from remnants of the former supercontinent Gondwana around 80 million years ago. A study conducted by Yohan Pillon et al. found, however, that the crown age (the age of the most recent common ancestor of all living and extinct species in the clade) of the clade of {{i}}Geissois{{/i}} trees on Grande Terre is 7.3 million years; Pillon et al. further found that the crown age of the clade of {{i}}Geissois{{/i}} trees in the South Pacific generally is also approximately 7.3 million years.", "questionText": "Which choice best describes the overall structure of the text?", "choices": ["It presents a possibility that some researchers have raised, then describes a study that clarifies their reasons for doing so.", "It describes an idea that some researchers have put forward, then presents study results that are incompatible with that idea.", "It identifies a discrepancy between a hypothesis some researchers have proposed and related research findings, then explains that discrepancy.", "It explains a view some researchers have advanced, then discusses study results that led them to reconsider that view."], "correctAnswer": 1, "difficulty": null}]};
